type MarkdownCodeLineHtmlRequest = MarkdownCodeHighlightLineRequest & {
  highlightPattern: string;
  key: string;
  languageId: string;
};

type MarkdownCodeHighlightTaskHandle =
  | { id: number; kind: "idle" }
  | { id: number; kind: "timeout" };

type MarkdownCodeHighlightIdleWindow = Window &
  typeof globalThis & {
    cancelIdleCallback?: Window["cancelIdleCallback"];
    requestIdleCallback?: Window["requestIdleCallback"];
  };

const resolvedMarkdownCodeLineHtml = new Map<string, string | null>();
const pendingMarkdownCodeLineHtml = new Map<
  string,
  MarkdownCodeLineHtmlRequest
>();
const markdownCodeLineHtmlSubscribers = new Map<string, Set<() => void>>();
const activeWorkerRequests = new Map<
  number,
  readonly MarkdownCodeLineHtmlRequest[]
>();

let markdownCodeHighlightFlushHandle: MarkdownCodeHighlightTaskHandle | null =
  null;
let markdownCodeHighlightWorker: Worker | null = null;
let isMarkdownCodeHighlightWorkerFailed = false;
let markdownCodeHighlightRequestId = 0;

export function isSafeHighlightedCodeLine(line: number) {
  return Number.isInteger(line) && line > 0 && line <= 100_000;
}

export function normalizeCodeLanguage(language: string | null) {
  const value = (language ?? "text").toLowerCase();
  const aliases: Record<string, string> = {
    bash: "shell",
    docker: "dockerfile",
    javascript: "js",
    jsonc: "json",
    md: "markdown",
    patch: "diff",
    rb: "ruby",
    "shell-session": "shell",
    terminal: "shell",
    typescript: "ts",
    yml: "yaml",
  };
  return aliases[value] ?? value;
}

export function diffLineKind(line: string) {
  if (line.startsWith("+") && !line.startsWith("+++")) return "add";
  if (line.startsWith("-") && !line.startsWith("---")) return "remove";
  return null;
}

export function renderCodeLine({
  fallbackLanguage,
  line,
  lineHtml,
  pattern,
}: {
  fallbackLanguage: string;
  line: string;
  lineHtml: string | undefined;
  pattern: string;
}) {
  if (lineHtml !== undefined) {
    return (
      <span
        data-pretext-code-line-html=""
        dangerouslySetInnerHTML={{ __html: lineHtml }}
      />
    );
  }
  if (!pattern) return renderFallbackCodeTokens(line || " ", fallbackLanguage);
  const index = line.indexOf(pattern);
  if (index < 0) return renderFallbackCodeTokens(line || " ", fallbackLanguage);
  return (
    <>
      {renderFallbackCodeTokens(line.slice(0, index), fallbackLanguage)}
      <span data-highlighted-chars="">{pattern}</span>
      {renderFallbackCodeTokens(
        line.slice(index + pattern.length),
        fallbackLanguage,
      )}
    </>
  );
}

export function useMarkdownCodeLineHtml({
  end,
  highlightPattern,
  language,
  sourceLines,
  start,
}: {
  end: number;
  highlightPattern: string;
  language: string;
  sourceLines: readonly string[];
  start: number;
}) {
  const requests = React.useMemo(
    () =>
      createMarkdownCodeLineHtmlRequests({
        end,
        highlightPattern,
        language,
        sourceLines,
        start,
      }),
    [end, highlightPattern, language, sourceLines, start],
  );
  const subscribe = React.useCallback(
    (onStoreChange: () => void) => {
      for (const request of requests) {
        let subscribers = markdownCodeLineHtmlSubscribers.get(request.key);
        if (!subscribers) {
          subscribers = new Set();
          markdownCodeLineHtmlSubscribers.set(request.key, subscribers);
        }
        subscribers.add(onStoreChange);
        ensureMarkdownCodeLineHtml(request);
      }
      return () => {
        for (const request of requests) {
          const subscribers = markdownCodeLineHtmlSubscribers.get(request.key);
          if (!subscribers) continue;
          subscribers.delete(onStoreChange);
          if (!subscribers.size) {
            markdownCodeLineHtmlSubscribers.delete(request.key);
          }
        }
      };
    },
    [requests],
  );
  const getSnapshot = React.useCallback(
    () =>
      requests
        .map((request) =>
          resolvedMarkdownCodeLineHtml.has(request.key) ? "1" : "0",
        )
        .join(""),
    [requests],
  );
  const resolvedVersion = React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    () => "",
  );

  return React.useMemo(() => {
    void resolvedVersion;
    const htmlByIndex = new Map<number, string>();
    for (const request of requests) {
      const html = resolvedMarkdownCodeLineHtml.get(request.key);
      if (typeof html === "string") htmlByIndex.set(request.index, html);
    }
    return htmlByIndex;
  }, [requests, resolvedVersion]);
}

function createMarkdownCodeLineHtmlRequests({
  end,
  highlightPattern,
  language,
  sourceLines,
  start,
}: {
  end: number;
  highlightPattern: string;
  language: string;
  sourceLines: readonly string[];
  start: number;
}) {
  const languageId = prismLanguageForMarkdownCode(language);
  if (!languageId) return [];

  const requests: MarkdownCodeLineHtmlRequest[] = [];
  const boundedStart = Math.max(0, Math.min(start, sourceLines.length));
  const boundedEnd = Math.max(boundedStart, Math.min(end, sourceLines.length));
  for (let index = boundedStart; index < boundedEnd; index += 1) {
    const line = sourceLines[index] ?? "";
    requests.push({
      highlightPattern,
      index,
      key: markdownCodeLineHtmlKey({
        highlightPattern,
        languageId,
        line,
      }),
      languageId,
      line,
    });
  }
  return requests;
}

function ensureMarkdownCodeLineHtml(request: MarkdownCodeLineHtmlRequest) {
  if (
    resolvedMarkdownCodeLineHtml.has(request.key) ||
    pendingMarkdownCodeLineHtml.has(request.key)
  ) {
    return;
  }
  pendingMarkdownCodeLineHtml.set(request.key, request);
  scheduleMarkdownCodeHighlightFlush();
}

function scheduleMarkdownCodeHighlightFlush() {
  if (markdownCodeHighlightFlushHandle) return;
  markdownCodeHighlightFlushHandle = scheduleMarkdownCodeHighlightTask(() => {
    markdownCodeHighlightFlushHandle = null;
    flushPendingMarkdownCodeHighlights();
  });
}

function flushPendingMarkdownCodeHighlights() {
  const firstRequest = pendingMarkdownCodeLineHtml.values().next().value;
  if (!firstRequest) return;

  const requests: MarkdownCodeLineHtmlRequest[] = [];
  for (const request of pendingMarkdownCodeLineHtml.values()) {
    if (
      request.languageId !== firstRequest.languageId ||
      request.highlightPattern !== firstRequest.highlightPattern
    ) {
      continue;
    }
    pendingMarkdownCodeLineHtml.delete(request.key);
    requests.push(request);
    if (requests.length >= MARKDOWN_CODE_HIGHLIGHT_BATCH_SIZE) break;
  }

  if (requests.length === 0) return;
  if (canUseMarkdownCodeHighlightWorker()) {
    requestMarkdownCodeHighlightWorker(requests);
  } else {
    void highlightMarkdownCodeLinesOnMainThread(requests);
  }
  if (pendingMarkdownCodeLineHtml.size > 0)
    scheduleMarkdownCodeHighlightFlush();
}

function canUseMarkdownCodeHighlightWorker() {
  return (
    !isMarkdownCodeHighlightWorkerFailed &&
    typeof Worker !== "undefined" &&
    typeof window !== "undefined"
  );
}

function requestMarkdownCodeHighlightWorker(
  requests: readonly MarkdownCodeLineHtmlRequest[],
) {
  const worker = getMarkdownCodeHighlightWorker();
  if (!worker) {
    void highlightMarkdownCodeLinesOnMainThread(requests);
    return;
  }

  markdownCodeHighlightRequestId += 1;
  const requestId = markdownCodeHighlightRequestId;
  activeWorkerRequests.set(requestId, requests);
  const firstRequest = requests[0]!;
  const request: MarkdownCodeHighlightWorkerRequest = {
    generation: MARKDOWN_CODE_HIGHLIGHT_RENDERER_VERSION,
    highlightPattern: firstRequest.highlightPattern,
    languageId: firstRequest.languageId,
    lines: requests.map(({ index, line }) => ({ index, line })),
    requestId,
    type: "highlight",
  };
  worker.postMessage(request);
}

function getMarkdownCodeHighlightWorker() {
  if (markdownCodeHighlightWorker) return markdownCodeHighlightWorker;
  try {
    markdownCodeHighlightWorker = new Worker(
      new URL(
        "./markdown-greenfield-code-highlight.worker.ts",
        import.meta.url,
      ),
      { type: "module" },
    );
    markdownCodeHighlightWorker.onmessage = (
      event: MessageEvent<MarkdownCodeHighlightWorkerResponse>,
    ) => handleMarkdownCodeHighlightWorkerMessage(event.data);
    markdownCodeHighlightWorker.onerror = () =>
      failMarkdownCodeHighlightWorker();
    markdownCodeHighlightWorker.onmessageerror = () =>
      failMarkdownCodeHighlightWorker();
    return markdownCodeHighlightWorker;
  } catch {
    isMarkdownCodeHighlightWorkerFailed = true;
    return null;
  }
}

function handleMarkdownCodeHighlightWorkerMessage(
  message: MarkdownCodeHighlightWorkerResponse,
) {
  const requests = activeWorkerRequests.get(message.requestId);
  if (
    !requests ||
    message.generation !== MARKDOWN_CODE_HIGHLIGHT_RENDERER_VERSION
  ) {
    return;
  }
  activeWorkerRequests.delete(message.requestId);
  if (message.type === "error") {
    resolveMarkdownCodeLineHtmlRequests(
      requests.map((request) => ({ html: null, index: request.index })),
      requests,
    );
    return;
  }
  resolveMarkdownCodeLineHtmlRequests(message.results, requests);
}

function failMarkdownCodeHighlightWorker() {
  const activeRequests = Array.from(activeWorkerRequests.values()).flat();
  activeWorkerRequests.clear();
  markdownCodeHighlightWorker?.terminate();
  markdownCodeHighlightWorker = null;
  isMarkdownCodeHighlightWorkerFailed = true;
  if (activeRequests.length) {
    void highlightMarkdownCodeLinesOnMainThread(activeRequests);
  }
}

async function highlightMarkdownCodeLinesOnMainThread(
  requests: readonly MarkdownCodeLineHtmlRequest[],
) {
  const firstRequest = requests[0];
  if (!firstRequest) return;
  try {
    await ensureCodePrismLanguage(firstRequest.languageId);
    resolveMarkdownCodeLineHtmlRequests(
      requests.map((request) => ({
        html: shouldTokenizeCodeLine(request.line)
          ? markdownCodeTokensToHtml({
              highlightPattern: request.highlightPattern,
              line: request.line,
              tokens: tokenizePrismCodeLine(request.languageId, request.line),
            })
          : null,
        index: request.index,
      })),
      requests,
    );
  } catch {
    resolveMarkdownCodeLineHtmlRequests(
      requests.map((request) => ({ html: null, index: request.index })),
      requests,
    );
  }
}

function resolveMarkdownCodeLineHtmlRequests(
  results: readonly MarkdownCodeHighlightLineResult[],
  requests: readonly MarkdownCodeLineHtmlRequest[],
) {
  const requestsByIndex = new Map(
    requests.map((request) => [request.index, request] as const),
  );
  const resolvedKeys: string[] = [];
  for (const result of results) {
    const request = requestsByIndex.get(result.index);
    if (!request) continue;
    resolvedMarkdownCodeLineHtml.set(request.key, result.html);
    resolvedKeys.push(request.key);
  }
  trimMarkdownCodeLineHtmlCache();
  notifyMarkdownCodeLineHtmlSubscribers(resolvedKeys);
}

function notifyMarkdownCodeLineHtmlSubscribers(keys: readonly string[]) {
  const subscribers = new Set<() => void>();
  for (const key of keys) {
    for (const subscriber of markdownCodeLineHtmlSubscribers.get(key) ?? []) {
      subscribers.add(subscriber);
    }
  }
  for (const subscriber of subscribers) subscriber();
}

function trimMarkdownCodeLineHtmlCache() {
  while (
    resolvedMarkdownCodeLineHtml.size > MARKDOWN_CODE_HIGHLIGHT_CACHE_LIMIT
  ) {
    const oldestKey = resolvedMarkdownCodeLineHtml.keys().next().value;
    if (oldestKey === undefined) break;
    resolvedMarkdownCodeLineHtml.delete(oldestKey);
  }
}

function scheduleMarkdownCodeHighlightTask(callback: () => void) {
  if (typeof window === "undefined") {
    const id = setTimeout(callback, 0) as unknown as number;
    return { id, kind: "timeout" as const };
  }
  const browserWindow = window as MarkdownCodeHighlightIdleWindow;
  if (browserWindow.requestIdleCallback) {
    return {
      id: browserWindow.requestIdleCallback(callback, { timeout: 120 }),
      kind: "idle" as const,
    };
  }
  return {
    id: browserWindow.setTimeout(callback, 0),
    kind: "timeout" as const,
  };
}

export function resetMarkdownCodeHighlightForTests() {
  resolvedMarkdownCodeLineHtml.clear();
  pendingMarkdownCodeLineHtml.clear();
  markdownCodeLineHtmlSubscribers.clear();
  activeWorkerRequests.clear();
  if (markdownCodeHighlightFlushHandle) {
    cancelMarkdownCodeHighlightTask(markdownCodeHighlightFlushHandle);
  }
  markdownCodeHighlightFlushHandle = null;
  markdownCodeHighlightWorker?.terminate();
  markdownCodeHighlightWorker = null;
  isMarkdownCodeHighlightWorkerFailed = false;
  markdownCodeHighlightRequestId = 0;
}

function cancelMarkdownCodeHighlightTask(
  handle: MarkdownCodeHighlightTaskHandle,
) {
  if (typeof window === "undefined") {
    clearTimeout(handle.id);
    return;
  }
  const browserWindow = window as MarkdownCodeHighlightIdleWindow;
  if (handle.kind === "idle") {
    browserWindow.cancelIdleCallback?.(handle.id);
    return;
  }
  browserWindow.clearTimeout(handle.id);
}

function markdownCodeLineHtmlKey({
  highlightPattern,
  languageId,
  line,
}: {
  highlightPattern: string;
  languageId: string;
  line: string;
}) {
  return [
    MARKDOWN_CODE_HIGHLIGHT_RENDERER_VERSION,
    languageId,
    highlightPattern,
    line,
  ].join("\0");
}

function prismLanguageForMarkdownCode(language: string) {
  const aliases: Record<string, string> = {
    dockerfile: "dockerfile",
    js: "javascript",
    shell: "bash",
    ts: "typescript",
  };
  const languageId = aliases[language] ?? language;
  if (languageId === "text" || languageId === "plaintext") return "";
  return languageId;
}

function renderFallbackCodeTokens(line: string, language: string) {
  const tokens = tokenizeFallbackCodeLine(line, language);
  if (!tokens.length) return " ";
  return tokens.map((token, index) =>
    token.kind === "plain" ? (
      <React.Fragment key={index}>{token.value}</React.Fragment>
    ) : (
      <span
        key={index}
        className={codeTokenClassName(token.kind)}
        data-pretext-code-token={token.kind}
      >
        {token.value}
      </span>
    ),
  );
}

type CodeToken = {
  kind: "comment" | "keyword" | "literal" | "number" | "plain" | "string";
  value: string;
};

function tokenizeFallbackCodeLine(line: string, language: string): CodeToken[] {
  if (!line) return [];
  if (language === "diff") return tokenizeDiffLine(line);
  if (language === "json") return tokenizeJsonLikeLine(line);
  if (language === "yaml") return tokenizeYamlLine(line);
  if (
    language === "js" ||
    language === "jsx" ||
    language === "ts" ||
    language === "tsx"
  ) {
    return tokenizeCStyleLine(line);
  }
  if (
    language === "shell" ||
    language === "bash" ||
    language === "dockerfile"
  ) {
    return tokenizeShellLine(line);
  }
  return [{ kind: "plain", value: line }];
}

function tokenizeCStyleLine(line: string): CodeToken[] {
  const commentIndex = line.indexOf("//");
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line;
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : "";
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:as|async|await|break|case|catch|class|const|continue|default|do|else|export|extends|false|finally|for|from|function|if|import|in|instanceof|interface|let|new|null|of|return|satisfies|switch|throw|true|try|type|typeof|undefined|var|while|yield)\b|\b\d+(?:\.\d+)?\b)/g,
      classifyCStyleToken,
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ];
}

function classifyCStyleToken(value: string): CodeToken["kind"] {
  if (/^["'`]/.test(value)) return "string";
  if (/^\d/.test(value)) return "number";
  if (/^(?:true|false|null|undefined)$/.test(value)) return "literal";
  return "keyword";
}

function tokenizeJsonLikeLine(line: string): CodeToken[] {
  return tokenizeByPattern(
    line,
    /("(?:\\.|[^"\\])*"|\b(?:true|false|null)\b|-?\b\d+(?:\.\d+)?(?:e[+-]?\d+)?\b)/gi,
    (value) => {
      if (/^"/.test(value)) return "string";
      if (/^(?:true|false|null)$/i.test(value)) return "literal";
      return "number";
    },
  );
}

function tokenizeYamlLine(line: string): CodeToken[] {
  const commentIndex = line.indexOf("#");
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line;
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : "";
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:true|false|null)\b|-?\b\d+(?:\.\d+)?\b)/gi,
      (value) => {
        if (/^["']/.test(value)) return "string";
        if (/^(?:true|false|null)$/i.test(value)) return "literal";
        return "number";
      },
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ];
}

function tokenizeShellLine(line: string): CodeToken[] {
  const commentIndex = line.search(/(^|\s)#/);
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line;
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : "";
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:cd|cp|curl|echo|export|git|grep|mkdir|mv|node|npm|pnpm|rm|sed|test|yarn)\b)/g,
      (value) => (/^["']/.test(value) ? "string" : "keyword"),
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ];
}

function tokenizeDiffLine(line: string): CodeToken[] {
  if (line.startsWith("+") && !line.startsWith("+++")) {
    return [{ kind: "literal", value: line }];
  }
  if (line.startsWith("-") && !line.startsWith("---")) {
    return [{ kind: "comment", value: line }];
  }
  return [{ kind: "plain", value: line }];
}

function tokenizeByPattern(
  line: string,
  pattern: RegExp,
  classify: (value: string) => CodeToken["kind"],
): CodeToken[] {
  const tokens: CodeToken[] = [];
  let cursor = 0;
  for (const match of line.matchAll(pattern)) {
    const index = match.index ?? 0;
    if (index > cursor) {
      tokens.push({ kind: "plain", value: line.slice(cursor, index) });
    }
    const value = match[0];
    tokens.push({ kind: classify(value), value });
    cursor = index + value.length;
  }
  if (cursor < line.length) {
    tokens.push({ kind: "plain", value: line.slice(cursor) });
  }
  return tokens;
}

function codeTokenClassName(kind: CodeToken["kind"]) {
  switch (kind) {
    case "comment":
      return "text-muted-foreground italic";
    case "keyword":
      return "font-semibold text-sky-700 dark:text-sky-300";
    case "literal":
      return "text-purple-700 dark:text-purple-300";
    case "number":
      return "text-amber-700 dark:text-amber-300";
    case "string":
      return "text-emerald-700 dark:text-emerald-300";
    default:
      return "";
  }
}

"use client";

import * as React from "react";
import { Check, Clipboard } from "lucide-react";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";
import {
  MERMAID_VIEWER_STYLES,
  describeDiagram,
  estimateDiagramBodyHeight,
  readDiagramLimitMessage,
  renderDiagram,
  type DiagramState,
} from "@/components/ui/mermaid-renderer";

export { resetMermaidRendererForTests as resetMarkdownMermaidRendererForTests } from "@/components/ui/mermaid-renderer";

const MERMAID_VIEWPORT_ROOT_MARGIN = "640px 0px";

// A per-instance async store for one diagram's mermaid render. Kept per
// component (not module-global) so instances never share state — no cross-
// render notify fan-out and no shared cache keyed by a render-order id.
type MermaidDiagramStore = {
  key: string;
  result: DiagramState | null;
  listeners: Set<() => void>;
};

export function MarkdownGreenfieldDiagram({
  caption,
  componentName,
  onContentReady,
  source,
  title,
}: {
  caption?: string;
  componentName?: string;
  onContentReady?: () => void;
  source: string;
  title?: string;
}) {
  const limitMessage = React.useMemo(
    () => readDiagramLimitMessage(source),
    [source],
  );
  const diagramId = React.useId().replace(/:/g, "");
  const elementId = `markdown-diagram-${diagramId}`;
  const description = React.useMemo(() => describeDiagram(source), [source]);
  const bodyHeight = React.useMemo(
    () => estimateDiagramBodyHeight(source),
    [source],
  );
  const descriptionId = description
    ? `markdown-diagram-description-${diagramId}`
    : undefined;
  const captionId = caption
    ? `markdown-diagram-caption-${diagramId}`
    : undefined;
  const describedBy =
    [descriptionId, captionId].filter(Boolean).join(" ") || undefined;
  const [figureRef, isRenderEligible] = useMermaidRenderEligibility({
    disabled: Boolean(limitMessage),
    source,
  });

  // Derive the displayed state: a limit message fails immediately; otherwise the
  // state follows this instance's async mermaid store (loading until resolved).
  const storeRef = React.useRef<MermaidDiagramStore | null>(null);
  if (storeRef.current === null) {
    storeRef.current = { key: "", listeners: new Set(), result: null };
  }
  const store = storeRef.current;
  const renderKey =
    limitMessage || !isRenderEligible ? "" : `${elementId}\0${source}`;
  const subscribe = React.useCallback(
    (onStoreChange: () => void) => {
      store.listeners.add(onStoreChange);
      // Kick off (or restart on source change) the render here, in the store
      // subscription, so no effect is needed.
      if (!limitMessage && store.key !== renderKey) {
        store.key = renderKey;
        store.result = null;
        void renderDiagram(source, elementId).then((result) => {
          if (store.key !== renderKey) return;
          store.result = result;
          for (const listener of store.listeners) listener();
        });
      }
      return () => {
        store.listeners.delete(onStoreChange);
      };
    },
    [elementId, limitMessage, renderKey, source, store],
  );
  const getSnapshot = React.useCallback(
    () => (store.key === renderKey ? store.result : null),
    [renderKey, store],
  );
  const resolvedState = React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    () => null,
  );
  const state: DiagramState = limitMessage
    ? { status: "failed", message: limitMessage }
    : (resolvedState ?? { status: "loading" });

  useKeyedLayoutEffect(
    joinEffectKey([bodyHeight, onContentReady, state.status]),
    () => {
      onContentReady?.();
    },
  );

  return (
    <figure
      ref={figureRef}
      aria-describedby={describedBy}
      aria-label={title || "Mermaid diagram"}
      className="group bg-muted/30 my-5 min-h-40 overflow-hidden rounded-md border"
      data-diagram-language="mermaid"
      data-diagram-renderer={
        state.status === "ready" ? state.renderer : undefined
      }
      data-diagram-reserved-height={bodyHeight}
      data-diagram-state={state.status}
      data-pretext-component={componentName}
      role="group"
      style={
        {
          "--pretext-diagram-body-height": `${bodyHeight}px`,
        } as React.CSSProperties
      }
    >
      <div className="bg-muted/60 flex h-9 items-center gap-1 border-b px-3">
        <span className="text-muted-foreground min-w-0 truncate text-xs font-medium">
          {title || "mermaid"}
        </span>
        <DiagramCopyButton
          ariaLabel="Copy diagram source"
          className="ml-auto"
          text={source}
        />
        {state.status === "ready" ? (
          <DiagramCopyButton ariaLabel="Copy diagram SVG" text={state.svg} />
        ) : null}
      </div>
      {description ? (
        <p
          className="sr-only"
          data-pretext-diagram-description=""
          id={descriptionId}
        >
          {description}
        </p>
      ) : null}
      <div
        aria-label="Mermaid diagram body"
        className="h-(--pretext-diagram-body-height) overflow-auto p-4"
        data-pretext-diagram-body=""
        onKeyDown={(event) => {
          const element = event.currentTarget;
          if (event.key === "ArrowRight") {
            element.scrollLeft += 50;
            event.preventDefault();
          } else if (event.key === "ArrowLeft") {
            element.scrollLeft -= 50;
            event.preventDefault();
          } else if (event.key === "End") {
            element.scrollLeft = Math.max(
              0,
              element.scrollWidth - element.clientWidth,
            );
            event.preventDefault();
          } else if (event.key === "Home") {
            element.scrollLeft = 0;
            event.preventDefault();
          }
        }}
        role="region"
        tabIndex={0}
      >
        {state.status === "ready" ? (
          <>
            <style data-pretext-mermaid-styles="">
              {MERMAID_VIEWER_STYLES}
            </style>
            <div
              className="text-foreground"
              data-pretext-mermaid-svg=""
              dangerouslySetInnerHTML={{ __html: state.svg }}
            />
          </>
        ) : (
          <>
            {state.status === "failed" ? (
              <p
                className="border-destructive/25 bg-destructive/10 text-destructive mb-3 rounded border px-3 py-2 text-sm"
                data-pretext-diagram-error=""
                role="alert"
              >
                {state.message}
              </p>
            ) : null}
            <pre
              aria-label="Mermaid diagram source"
              className="text-muted-foreground m-0 overflow-x-auto font-mono text-[0.82em] leading-relaxed"
              tabIndex={0}
            >
              {source}
            </pre>
          </>
        )}
      </div>
      {caption ? (
        <figcaption
          className="bg-muted/30 text-muted-foreground border-t px-3 py-2 text-sm"
          data-pretext-diagram-caption=""
          id={captionId}
        >
          {caption}
        </figcaption>
      ) : null}
    </figure>
  );
}

function useMermaidRenderEligibility({
  disabled,
  source,
}: {
  disabled: boolean;
  source: string;
}) {
  const ref = React.useRef<HTMLElement | null>(null);
  const [isEligible, setIsEligible] = React.useState(
    () => !disabled && typeof IntersectionObserver === "undefined",
  );

  useKeyedLayoutEffect(joinEffectKey([disabled, source]), () => {
    if (disabled) {
      setIsEligible(false);
      return;
    }
    if (typeof IntersectionObserver === "undefined") {
      setIsEligible(true);
      return;
    }
    const element = ref.current;
    if (!element) return;
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[0];
        if (!entry?.isIntersecting && (entry?.intersectionRatio ?? 0) <= 0) {
          return;
        }
        setIsEligible(true);
        observer.disconnect();
      },
      { root: null, rootMargin: MERMAID_VIEWPORT_ROOT_MARGIN },
    );
    observer.observe(element);
    return () => observer.disconnect();
  });

  return [ref, isEligible] as const;
}

function DiagramCopyButton({
  ariaLabel,
  className,
  text,
}: {
  ariaLabel: string;
  className?: string;
  text: string;
}) {
  const [isCopied, setIsCopied] = React.useState(false);

  return (
    <button
      aria-label={isCopied ? "Copied" : ariaLabel}
      className={[
        "text-muted-foreground hover:bg-background hover:text-foreground focus-visible:ring-ring inline-flex size-7 items-center justify-center rounded-md transition focus-visible:ring-2 focus-visible:outline-none",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
      type="button"
      onClick={() => {
        void navigator.clipboard?.writeText(text).then(() => {
          setIsCopied(true);
          window.setTimeout(() => setIsCopied(false), 1200);
        });
      }}
    >
      {isCopied ? (
        <Check aria-hidden="true" className="size-3.5" />
      ) : (
        <Clipboard aria-hidden="true" className="size-3.5" />
      )}
    </button>
  );
}

"use client";

import type {
  MarkdownHastElement,
  MarkdownHastNode,
} from "./markdown-hast-types";
import {
  markdownSourceRangeFromPosition,
  markdownSourceTextForRange,
  type MarkdownSourceRange,
} from "./markdown-source-map";
import {
  createMarkdownUnifiedDocument,
  type MarkdownUnifiedDocument,
} from "./markdown-unified-pipeline";

const TARGET_CHUNK_SOURCE_LINES = 42;
const MAX_CHUNK_SOURCE_LINES = 64;
const HOSTILE_CODE_LINE_COUNT = 400;
const HOSTILE_HAST_NODE_COUNT = 3_000;
const HOSTILE_HAST_DEPTH = 80;
const HOSTILE_TEXT_LENGTH = 20_000;
const HOSTILE_TABLE_CELL_COUNT = 50_000;
const HOSTILE_TABLE_HAST_NODE_COUNT = 120_000;
const HOSTILE_TABLE_TEXT_LENGTH = 1_000_000;
const DOCUMENT_CACHE_LIMIT = 24;

const markdownGreenfieldDocumentCache = new Map<
  string,
  {
    document: MarkdownGreenfieldDocument;
    text: string;
  }
>();

export type MarkdownGreenfieldBlockKind =
  | "blockquote"
  | "code"
  | "component"
  | "diagram"
  | "footnotes"
  | "frontmatter"
  | "heading"
  | "html"
  | "image"
  | "list"
  | "math"
  | "paragraph"
  | "table"
  | "thematicBreak"
  | "unknown";

export type MarkdownGreenfieldDocument = {
  blocks: MarkdownGreenfieldBlock[];
  chunks: MarkdownGreenfieldChunk[];
  fragmentTargets: MarkdownGreenfieldFragmentTarget[];
  headings: MarkdownGreenfieldHeading[];
  lineCount: number;
  text: string;
  unified: MarkdownUnifiedDocument;
  wordCount: number;
};

export type MarkdownGreenfieldHeading = {
  blockId: string;
  id: string;
  sourceLine: number;
  text: string;
};

export type MarkdownGreenfieldFragmentTarget = {
  blockId: string;
  id: string;
  sourceLine: number;
};

export type MarkdownGreenfieldBlock = {
  hastChildren: MarkdownHastNode[];
  id: string;
  index: number;
  isGenerated: boolean;
  isHostile: boolean;
  kind: MarkdownGreenfieldBlockKind;
  sourceLineCount: number;
  sourceLineLengths: readonly number[];
  sourceRange: MarkdownSourceRange | null;
  sourceText: string;
};

export type MarkdownGreenfieldChunk = {
  blockIds: string[];
  hastChildren: MarkdownHastNode[];
  id: string;
  index: number;
  isHostile: boolean;
  nativeFindText: string;
  sourceEndLine: number;
  sourceLineCount: number;
  sourceRange: MarkdownSourceRange | null;
  sourceStartLine: number;
  sourceText: string;
};

export function createMarkdownGreenfieldDocument(
  markdown: string,
): MarkdownGreenfieldDocument {
  const text = markdown.length ? markdown : " ";
  const cacheKey = markdownGreenfieldDocumentTextKey(text);
  const cached = markdownGreenfieldDocumentCache.get(cacheKey);
  if (cached?.text === text) {
    markdownGreenfieldDocumentCache.delete(cacheKey);
    markdownGreenfieldDocumentCache.set(cacheKey, cached);
    return cached.document;
  }

  const document = createUncachedMarkdownGreenfieldDocument(text);
  markdownGreenfieldDocumentCache.set(cacheKey, {
    document,
    text,
  });
  while (markdownGreenfieldDocumentCache.size > DOCUMENT_CACHE_LIMIT) {
    const oldestKey = markdownGreenfieldDocumentCache.keys().next().value;
    if (!oldestKey) break;
    markdownGreenfieldDocumentCache.delete(oldestKey);
  }

  return document;
}

function createUncachedMarkdownGreenfieldDocument(
  text: string,
): MarkdownGreenfieldDocument {
  const unified = createMarkdownUnifiedDocument(text);
  normalizeMarkdownGreenfieldHeadingIds(unified.hast.children, unified);
  normalizeMarkdownGreenfieldTables(unified.hast.children);
  annotateMarkdownGreenfieldSourceMetadata(unified.hast.children, unified);
  const blocks = createMarkdownGreenfieldBlocks({ text, unified });
  const chunks = createMarkdownGreenfieldChunks({ blocks, text });
  const headings = createMarkdownGreenfieldHeadings(blocks);
  const fragmentTargets = createMarkdownGreenfieldFragmentTargets({
    blocks,
    unified,
  });

  return freezeMarkdownGreenfieldDocument({
    blocks,
    chunks,
    fragmentTargets,
    headings,
    lineCount: unified.sourceMap.lineCount,
    text,
    unified,
    wordCount: text.trim().split(/\s+/).filter(Boolean).length,
  });
}

export function findMarkdownGreenfieldHeadingById(
  document: MarkdownGreenfieldDocument,
  headingId: string,
) {
  const normalizedId = headingId.replace(/^#/, "");
  return document.headings.find((heading) => heading.id === normalizedId);
}

export function findMarkdownGreenfieldFragmentTargetById(
  document: MarkdownGreenfieldDocument,
  fragmentId: string,
) {
  const normalizedId = normalizeFragmentTargetId(fragmentId);
  return document.fragmentTargets.find((target) => target.id === normalizedId);
}

export function findMarkdownGreenfieldBlockById(
  document: MarkdownGreenfieldDocument,
  blockId: string,
) {
  return document.blocks.find((block) => block.id === blockId) ?? null;
}

export function findMarkdownGreenfieldChunkByBlockId(
  document: MarkdownGreenfieldDocument,
  blockId: string,
) {
  return (
    document.chunks.find((chunk) => chunk.blockIds.includes(blockId)) ?? null
  );
}

export function findMarkdownGreenfieldBlockBySourceLine(
  document: MarkdownGreenfieldDocument,
  sourceLine: number,
) {
  const line = clampSourceLine(sourceLine, document.lineCount);
  return (
    document.blocks.find((block) => {
      const range = block.sourceRange;
      return range && range.startLine <= line && range.endLine >= line;
    }) ?? null
  );
}

export function findMarkdownGreenfieldChunkBySourceLine(
  document: MarkdownGreenfieldDocument,
  sourceLine: number,
) {
  const block = findMarkdownGreenfieldBlockBySourceLine(document, sourceLine);
  if (block) return findMarkdownGreenfieldChunkByBlockId(document, block.id);

  const line = clampSourceLine(sourceLine, document.lineCount);
  return (
    document.chunks.find(
      (chunk) => chunk.sourceStartLine <= line && chunk.sourceEndLine >= line,
    ) ?? null
  );
}

export function findMarkdownGreenfieldBlockBySourceOffset(
  document: MarkdownGreenfieldDocument,
  sourceOffset: number,
) {
  const offset = clampSourceOffset(sourceOffset, document.text.length);
  return (
    document.blocks.find((block) => {
      const range = block.sourceRange;
      return range && range.startOffset <= offset && range.endOffset > offset;
    }) ?? null
  );
}

export function findMarkdownGreenfieldChunkBySourceOffset(
  document: MarkdownGreenfieldDocument,
  sourceOffset: number,
) {
  const block = findMarkdownGreenfieldBlockBySourceOffset(
    document,
    sourceOffset,
  );
  return block
    ? findMarkdownGreenfieldChunkByBlockId(document, block.id)
    : null;
}

function createMarkdownGreenfieldBlocks({
  text,
  unified,
}: {
  text: string;
  unified: MarkdownUnifiedDocument;
}) {
  const blocks: MarkdownGreenfieldBlock[] = [];

  for (const child of unified.hast.children) {
    if (isWhitespaceText(child)) continue;

    const directSourceRange = markdownSourceRangeFromPosition({
      position: child.position,
      sourceMap: unified.sourceMap,
    });
    const sourceRange =
      directSourceRange ?? markdownSyntheticSourceRangeForNode(child, unified);
    const kind = markdownBlockKindForHastChild(child);
    const sourceText = markdownSourceTextForRange({
      range: sourceRange,
      sourceMap: unified.sourceMap,
    });
    const normalizedSourceText =
      sourceText ||
      (sourceRange
        ? text.slice(sourceRange.startOffset, sourceRange.endOffset)
        : "");
    const sourceMetrics =
      markdownGreenfieldSourceMetricsForText(normalizedSourceText);
    const line = sourceRange?.startLine ?? unified.sourceMap.lineCount;
    const block: MarkdownGreenfieldBlock = {
      hastChildren: [child],
      id: `block-${blocks.length + 1}-${line}-${kind}`,
      index: blocks.length,
      isGenerated: !directSourceRange,
      isHostile: isHostileMarkdownGreenfieldBlock({
        child,
        kind,
        sourceLineCount: sourceMetrics.sourceLineCount,
        sourceText: normalizedSourceText,
      }),
      kind,
      sourceLineCount: sourceMetrics.sourceLineCount,
      sourceLineLengths: sourceMetrics.sourceLineLengths,
      sourceRange,
      sourceText: normalizedSourceText,
    };
    blocks.push(block);
  }

  if (!blocks.length) {
    const sourceMetrics = markdownGreenfieldSourceMetricsForText(text);
    blocks.push({
      hastChildren: [],
      id: "block-1-empty",
      index: 0,
      isGenerated: true,
      isHostile: false,
      kind: "paragraph",
      sourceLineCount: sourceMetrics.sourceLineCount,
      sourceLineLengths: sourceMetrics.sourceLineLengths,
      sourceRange: {
        endLine: 1,
        endOffset: text.length,
        startLine: 1,
        startOffset: 0,
      },
      sourceText: text,
    });
  }

  return blocks;
}

function createMarkdownGreenfieldChunks({
  blocks,
  text,
}: {
  blocks: readonly MarkdownGreenfieldBlock[];
  text: string;
}) {
  const chunks: MarkdownGreenfieldChunk[] = [];
  let current: MarkdownGreenfieldBlock[] = [];

  const flush = () => {
    if (!current.length) return;
    chunks.push(createChunk(current, chunks.length, text));
    current = [];
  };

  for (const block of blocks) {
    if (block.isHostile) {
      flush();
      current.push(block);
      flush();
      continue;
    }

    const nextLineCount = lineCountForBlocks(current, block);
    const startsNewChunk =
      current.length > 0 &&
      block.kind === "heading" &&
      nextLineCount >= TARGET_CHUNK_SOURCE_LINES;
    const exceedsMax =
      current.length > 0 && nextLineCount > MAX_CHUNK_SOURCE_LINES;

    if (startsNewChunk || exceedsMax) flush();
    current.push(block);
  }

  flush();
  return chunks;
}

function createChunk(
  blocks: readonly MarkdownGreenfieldBlock[],
  index: number,
  text: string,
): MarkdownGreenfieldChunk {
  const ranges = blocks
    .map((block) => block.sourceRange)
    .filter((range): range is MarkdownSourceRange => Boolean(range));
  const sourceRange = ranges.length
    ? {
        endLine: Math.max(...ranges.map((range) => range.endLine)),
        endOffset: Math.max(...ranges.map((range) => range.endOffset)),
        startLine: Math.min(...ranges.map((range) => range.startLine)),
        startOffset: Math.min(...ranges.map((range) => range.startOffset)),
      }
    : null;
  const sourceStartLine =
    sourceRange?.startLine ?? blocks[0]?.sourceRange?.startLine ?? 1;
  const sourceEndLine =
    sourceRange?.endLine ??
    blocks[blocks.length - 1]?.sourceRange?.endLine ??
    sourceStartLine;
  const sourceLineCount = sourceRange
    ? sourceEndLine - sourceStartLine + 1
    : Math.max(
        1,
        blocks.reduce((sum, block) => sum + block.sourceLineCount, 0),
      );
  const hastChildren = blocks.flatMap((block) => block.hastChildren);

  return {
    blockIds: blocks.map((block) => block.id),
    hastChildren,
    id: `chunk-${index + 1}-${sourceStartLine}`,
    index,
    isHostile: blocks.some((block) => block.isHostile),
    nativeFindText: nativeFindTextForHastChildren(hastChildren),
    sourceEndLine,
    sourceLineCount,
    sourceRange,
    sourceStartLine,
    sourceText: sourceRange
      ? text.slice(sourceRange.startOffset, sourceRange.endOffset)
      : "",
  };
}

function createMarkdownGreenfieldHeadings(
  blocks: readonly MarkdownGreenfieldBlock[],
) {
  return blocks.flatMap((block) => {
    const element = readHastElement(block.hastChildren[0]);
    if (!element || !/^h[1-6]$/.test(element.tagName)) return [];

    const id = readStringProperty(element.properties?.id);
    if (!id) return [];

    return [
      {
        blockId: block.id,
        id,
        sourceLine: block.sourceRange?.startLine ?? 1,
        text: extractHastText(element).trim(),
      },
    ];
  });
}

function createMarkdownGreenfieldFragmentTargets({
  blocks,
  unified,
}: {
  blocks: readonly MarkdownGreenfieldBlock[];
  unified: MarkdownUnifiedDocument;
}) {
  const targets = new Map<string, MarkdownGreenfieldFragmentTarget>();

  for (const block of blocks) {
    for (const child of block.hastChildren) {
      collectFragmentTargets({
        block,
        node: child,
        targets,
        unified,
      });
    }
  }

  return Array.from(targets.values());
}

function collectFragmentTargets({
  block,
  node,
  targets,
  unified,
}: {
  block: MarkdownGreenfieldBlock;
  node: MarkdownHastNode;
  targets: Map<string, MarkdownGreenfieldFragmentTarget>;
  unified: MarkdownUnifiedDocument;
}) {
  const element = readHastElement(node);
  if (!element) return;

  const id = readStringProperty(element.properties?.id);
  if (id) {
    const sourceRange =
      markdownSourceRangeFromPosition({
        position: element.position,
        sourceMap: unified.sourceMap,
      }) ?? block.sourceRange;
    const target = {
      blockId: block.id,
      id,
      sourceLine: sourceRange?.startLine ?? unified.sourceMap.lineCount,
    };

    for (const alias of fragmentTargetAliases(id)) {
      if (!targets.has(alias)) {
        targets.set(alias, { ...target, id: alias });
      }
    }
  }

  for (const child of element.children) {
    collectFragmentTargets({ block, node: child, targets, unified });
  }
}

function markdownSyntheticSourceRangeForNode(
  node: MarkdownHastNode,
  unified: MarkdownUnifiedDocument,
): MarkdownSourceRange | null {
  const ranges = collectMarkdownSourceRanges(node, unified);
  if (!ranges.length) return null;
  return {
    endLine: Math.max(...ranges.map((range) => range.endLine)),
    endOffset: Math.max(...ranges.map((range) => range.endOffset)),
    startLine: Math.min(...ranges.map((range) => range.startLine)),
    startOffset: Math.min(...ranges.map((range) => range.startOffset)),
  };
}

function collectMarkdownSourceRanges(
  node: MarkdownHastNode,
  unified: MarkdownUnifiedDocument,
): MarkdownSourceRange[] {
  const range = markdownSourceRangeFromPosition({
    position: node.position,
    sourceMap: unified.sourceMap,
  });
  const element = readHastElement(node);
  return [
    ...(range ? [range] : []),
    ...(element?.children ?? []).flatMap((child) =>
      collectMarkdownSourceRanges(child, unified),
    ),
  ];
}

function normalizeMarkdownGreenfieldHeadingIds(
  nodes: readonly MarkdownHastNode[],
  unified: MarkdownUnifiedDocument,
) {
  const usedIds = new Map<string, number>();
  for (const node of nodes) {
    normalizeHeadingIdsInNode(node, usedIds, unified);
  }
}

function normalizeHeadingIdsInNode(
  node: MarkdownHastNode,
  usedIds: Map<string, number>,
  unified: MarkdownUnifiedDocument,
) {
  const element = readHastElement(node);
  if (!element) return;

  if (/^h[1-6]$/.test(element.tagName)) {
    const visibleText = extractHastText(element);
    const markdownText = markdownHeadingTextFromSource(element, unified);
    const baseId = safeHeadingIdForText(
      markdownText.includes("__proto__") ? markdownText : visibleText,
    );
    const duplicateCount = usedIds.get(baseId) ?? 0;
    usedIds.set(baseId, duplicateCount + 1);
    element.properties = {
      ...element.properties,
      id: duplicateCount === 0 ? baseId : `${baseId}-${duplicateCount}`,
    };
  }

  for (const child of element.children) {
    normalizeHeadingIdsInNode(child, usedIds, unified);
  }
}

function markdownHeadingTextFromSource(
  element: MarkdownHastElement,
  unified: MarkdownUnifiedDocument,
) {
  const range = markdownSourceRangeFromPosition({
    position: element.position,
    sourceMap: unified.sourceMap,
  });
  if (!range) return "";
  return markdownSourceTextForRange({
    range,
    sourceMap: unified.sourceMap,
  })
    .replace(/^\s{0,3}#{1,6}[ \t]*/, "")
    .replace(/[ \t]+#*\s*$/, "")
    .trim();
}

function safeHeadingIdForText(text: string) {
  const slug =
    text
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^\w\s-]/g, "")
      .trim()
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-") || "section";

  return isDomClobberingId(slug) ? `section-${slug}` : slug;
}

function normalizeFragmentTargetId(fragmentId: string) {
  return decodeURIComponent(fragmentId.replace(/^#/, ""));
}

function fragmentTargetAliases(id: string) {
  const aliases = new Set<string>([normalizeFragmentTargetId(id)]);
  const withoutRepeatedClobberPrefix = id.replace(
    /^(user-content-)+/,
    "user-content-",
  );
  aliases.add(withoutRepeatedClobberPrefix);
  aliases.add(withoutRepeatedClobberPrefix.replace(/^user-content-/, ""));
  return Array.from(aliases).filter(Boolean);
}

function normalizeMarkdownGreenfieldTables(nodes: readonly MarkdownHastNode[]) {
  let tableIndex = 0;
  for (const node of nodes) {
    tableIndex = normalizeTablesInNode(node, tableIndex);
  }
}

function normalizeTablesInNode(node: MarkdownHastNode, tableIndex: number) {
  const element = readHastElement(node);
  if (!element) return tableIndex;

  if (element.tagName === "table") {
    normalizeTableElement(element, tableIndex);
    tableIndex += 1;
  }

  for (const child of element.children) {
    tableIndex = normalizeTablesInNode(child, tableIndex);
  }
  return tableIndex;
}

function normalizeTableElement(table: MarkdownHastElement, tableIndex: number) {
  const rows = tableRows(table);
  const headerIds = new Map<number, string>();

  rows.forEach((row, rowIndex) => {
    row.properties = {
      ...row.properties,
      ariaRowIndex: rowIndex + 1,
      dataPretextTableRowIndex: rowIndex + 1,
    };

    tableCells(row).forEach((cell, columnIndex) => {
      const column = columnIndex + 1;
      const properties = {
        ...cell.properties,
        ariaColIndex: column,
        dataPretextTableColumnIndex: column,
      };
      if (cell.tagName === "th") {
        const id = `markdown-table-${tableIndex + 1}-column-${column}`;
        headerIds.set(columnIndex, id);
        cell.properties = {
          ...properties,
          id,
          scope: "col",
        };
      } else {
        cell.properties = {
          ...properties,
          headers: headerIds.get(columnIndex),
        };
      }
    });
  });
}

function annotateMarkdownGreenfieldSourceMetadata(
  nodes: readonly MarkdownHastNode[],
  unified: MarkdownUnifiedDocument,
) {
  for (const node of nodes) {
    annotateSourceMetadataInNode(node, unified);
  }
}

function annotateSourceMetadataInNode(
  node: MarkdownHastNode,
  unified: MarkdownUnifiedDocument,
) {
  const element = readHastElement(node);
  if (!element) return;

  const sourceRange = markdownSourceRangeFromPosition({
    position: element.position,
    sourceMap: unified.sourceMap,
  });
  if (sourceRange) {
    element.properties = {
      ...element.properties,
      dataPretextSourceEndLine: sourceRange.endLine,
      dataPretextSourceEndOffset: sourceRange.endOffset,
      dataPretextSourceStartLine: sourceRange.startLine,
      dataPretextSourceStartOffset: sourceRange.startOffset,
    };
  }

  for (const child of element.children) {
    annotateSourceMetadataInNode(child, unified);
  }
}

function tableRows(element: MarkdownHastElement) {
  const rows: MarkdownHastElement[] = [];
  for (const child of element.children) {
    const childElement = readHastElement(child);
    if (!childElement) continue;
    if (childElement.tagName === "tr") {
      rows.push(childElement);
    } else if (
      childElement.tagName === "thead" ||
      childElement.tagName === "tbody" ||
      childElement.tagName === "tfoot"
    ) {
      rows.push(...tableRows(childElement));
    }
  }
  return rows;
}

function tableCells(row: MarkdownHastElement) {
  return row.children
    .map(readHastElement)
    .filter(
      (child): child is MarkdownHastElement =>
        child?.tagName === "td" || child?.tagName === "th",
    );
}

function isDomClobberingId(id: string) {
  return [
    "__proto__",
    "constructor",
    "document",
    "forms",
    "history",
    "location",
    "name",
    "prototype",
    "window",
  ].includes(id);
}

function markdownBlockKindForHastChild(
  child: MarkdownHastNode,
): MarkdownGreenfieldBlockKind {
  const element = readHastElement(child);
  if (!element) return child.type === "text" ? "paragraph" : "unknown";

  if (element.properties?.dataFootnotes != null) return "footnotes";
  if (element.properties?.dataMarkdownFrontmatter != null) return "frontmatter";
  if (/^h[1-6]$/.test(element.tagName)) return "heading";
  if (isMarkdownDiagramElement(element)) return "diagram";
  if (isMarkdownComponentElement(element)) return "component";
  if (isDisplayMathElement(element)) return "math";

  switch (element.tagName) {
    case "blockquote":
      return "blockquote";
    case "hr":
      return "thematicBreak";
    case "ol":
    case "ul":
      return "list";
    case "p":
      if (isDisplayMathElement(element)) return "math";
      return firstElementChild(element)?.tagName === "img"
        ? "image"
        : "paragraph";
    case "pre":
      if (isMermaidCodeElement(element)) return "diagram";
      return "code";
    case "table":
      return "table";
    default:
      return "html";
  }
}

function isMarkdownDiagramElement(element: MarkdownHastElement) {
  return (
    readStringProperty(element.properties?.dataPretextComponentName) ===
    "Diagram"
  );
}

function isMarkdownComponentElement(element: MarkdownHastElement) {
  return (
    element.properties?.dataPretextComponentName != null ||
    element.properties?.dataPretextComponentFallback != null ||
    element.properties?.dataPretextCalloutKind != null
  );
}

function isDisplayMathElement(element: MarkdownHastElement): boolean {
  if (
    hasClassName(element, "katex-display") ||
    hasClassName(element, "math-display")
  )
    return true;
  return element.children
    .map(readHastElement)
    .some((child) => child != null && isDisplayMathElement(child));
}

function isMermaidCodeElement(element: MarkdownHastElement) {
  const code = firstElementChild(element);
  return (
    code?.tagName === "code" &&
    ["language-mermaid", "language-mmd", "language-mermaid-js"].some(
      (className) => hasClassName(code, className),
    )
  );
}

function hasClassName(element: MarkdownHastElement, className: string) {
  const classes = element.properties?.className;
  return Array.isArray(classes)
    ? classes.includes(className)
    : typeof classes === "string" && classes.split(/\s+/).includes(className);
}

function isHostileMarkdownGreenfieldBlock({
  child,
  kind,
  sourceLineCount,
  sourceText,
}: {
  child: MarkdownHastNode;
  kind: MarkdownGreenfieldBlockKind;
  sourceLineCount: number;
  sourceText: string;
}) {
  if (kind === "table") {
    if (sourceText.length > HOSTILE_TABLE_TEXT_LENGTH) return true;
    if (countTableCells(child) > HOSTILE_TABLE_CELL_COUNT) return true;
    if (countHastNodes(child) > HOSTILE_TABLE_HAST_NODE_COUNT) return true;
    if (maxHastDepth(child) > HOSTILE_HAST_DEPTH) return true;
    return false;
  }
  if (sourceText.length > HOSTILE_TEXT_LENGTH) return true;
  if (countHastNodes(child) > HOSTILE_HAST_NODE_COUNT) return true;
  if (maxHastDepth(child) > HOSTILE_HAST_DEPTH) return true;
  if (kind === "code" && sourceLineCount > HOSTILE_CODE_LINE_COUNT) {
    return true;
  }
  return false;
}

function countHastNodes(node: MarkdownHastNode): number {
  const element = readHastElement(node);
  return (
    1 +
    (element?.children ?? []).reduce(
      (sum, child) => sum + countHastNodes(child),
      0,
    )
  );
}

function maxHastDepth(node: MarkdownHastNode): number {
  const element = readHastElement(node);
  if (!element?.children.length) return 1;
  return 1 + Math.max(...element.children.map(maxHastDepth));
}

function lineCountForBlocks(
  blocks: readonly MarkdownGreenfieldBlock[],
  nextBlock: MarkdownGreenfieldBlock,
) {
  let fallbackLineCount = 0;
  let sourceEndLine = 0;
  let sourceStartLine = 0;

  for (const block of blocks) {
    fallbackLineCount += block.sourceLineCount;
    const range = block.sourceRange;
    if (!range) continue;
    sourceStartLine = sourceStartLine
      ? Math.min(sourceStartLine, range.startLine)
      : range.startLine;
    sourceEndLine = Math.max(sourceEndLine, range.endLine);
  }
  fallbackLineCount += nextBlock.sourceLineCount;
  const nextRange = nextBlock.sourceRange;
  if (nextRange) {
    sourceStartLine = sourceStartLine
      ? Math.min(sourceStartLine, nextRange.startLine)
      : nextRange.startLine;
    sourceEndLine = Math.max(sourceEndLine, nextRange.endLine);
  }

  if (!sourceStartLine) return Math.max(1, fallbackLineCount);
  return sourceEndLine - sourceStartLine + 1;
}

function countTableCells(node: MarkdownHastNode): number {
  const element = readHastElement(node);
  if (!element) return 0;
  const self = element.tagName === "td" || element.tagName === "th" ? 1 : 0;
  return (
    self +
    (element.children ?? []).reduce(
      (sum, child) => sum + countTableCells(child),
      0,
    )
  );
}

function markdownGreenfieldSourceMetricsForText(sourceText: string) {
  const sourceLineLengths: number[] = [];
  let sourceLineLength = 0;

  for (let index = 0; index < sourceText.length; index += 1) {
    const charCode = sourceText.charCodeAt(index);
    if (charCode === 13) {
      sourceLineLengths.push(sourceLineLength);
      sourceLineLength = 0;
      if (sourceText.charCodeAt(index + 1) === 10) index += 1;
      continue;
    }
    if (charCode === 10 || charCode === 0x2028 || charCode === 0x2029) {
      sourceLineLengths.push(sourceLineLength);
      sourceLineLength = 0;
      continue;
    }
    sourceLineLength += 1;
  }

  sourceLineLengths.push(sourceLineLength);
  return {
    sourceLineCount: sourceLineLengths.length,
    sourceLineLengths,
  };
}

function readHastElement(node: unknown): MarkdownHastElement | null {
  return node &&
    typeof node === "object" &&
    (node as MarkdownHastElement).type === "element"
    ? (node as MarkdownHastElement)
    : null;
}

function firstElementChild(element: MarkdownHastElement) {
  return element.children.map(readHastElement).find(Boolean) ?? null;
}

function isWhitespaceText(node: MarkdownHastNode) {
  return (
    node.type === "text" &&
    typeof node.value === "string" &&
    node.value.trim() === ""
  );
}

function readStringProperty(value: unknown) {
  if (typeof value === "string") return value;
  if (Array.isArray(value)) return value.filter(Boolean).join(" ");
  return "";
}

function extractHastText(node: MarkdownHastNode): string {
  if (node.type === "text" && typeof node.value === "string") return node.value;
  const element = readHastElement(node);
  if (!element) return "";
  return element.children.map(extractHastText).join("");
}

function nativeFindTextForHastChildren(children: readonly MarkdownHastNode[]) {
  const text: string[] = [];
  const stack = [...children].reverse();
  while (stack.length) {
    const node = stack.pop();
    if (!node) continue;
    if (node.type === "text" && typeof node.value === "string") {
      text.push(node.value);
      continue;
    }

    const element = readHastElement(node);
    if (!element) continue;
    if (element.tagName === "script" || element.tagName === "style") continue;
    for (let index = element.children.length - 1; index >= 0; index -= 1) {
      stack.push(element.children[index]!);
    }
  }
  return text.join(" ").trim();
}

function freezeMarkdownHastNode(node: unknown) {
  if (!node || typeof node !== "object" || Object.isFrozen(node)) return;

  const record = node as Record<string, unknown>;
  for (const value of Object.values(record)) {
    if (Array.isArray(value)) {
      value.forEach(freezeMarkdownHastNode);
      Object.freeze(value);
      continue;
    }
    if (value && typeof value === "object") {
      freezeMarkdownHastNode(value);
    }
  }
  Object.freeze(node);
}

export function freezeMarkdownGreenfieldDocument(
  document: MarkdownGreenfieldDocument,
) {
  freezeMarkdownHastNode(document.unified.hast);
  for (const block of document.blocks) {
    if (block.sourceRange) Object.freeze(block.sourceRange);
    Object.freeze(block.hastChildren);
    Object.freeze(block.sourceLineLengths);
    Object.freeze(block);
  }
  for (const chunk of document.chunks) {
    if (chunk.sourceRange) Object.freeze(chunk.sourceRange);
    Object.freeze(chunk.blockIds);
    Object.freeze(chunk.hastChildren);
    Object.freeze(chunk);
  }
  for (const heading of document.headings) Object.freeze(heading);
  for (const target of document.fragmentTargets) Object.freeze(target);
  Object.freeze(document.blocks);
  Object.freeze(document.chunks);
  Object.freeze(document.headings);
  Object.freeze(document.fragmentTargets);
  return Object.freeze(document);
}

export function markdownGreenfieldDocumentTextKey(text: string) {
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${text.length}:${(hash >>> 0).toString(36)}`;
}

function clampSourceLine(line: number, lineCount: number) {
  if (!Number.isFinite(line)) return 1;
  return Math.max(1, Math.min(lineCount, Math.floor(line)));
}

function clampSourceOffset(offset: number, textLength: number) {
  if (!Number.isFinite(offset)) return 0;
  return Math.max(0, Math.min(textLength, Math.floor(offset)));
}

"use client";

import * as React from "react";

import {
  createMarkdownGreenfieldDocument,
  freezeMarkdownGreenfieldDocument,
  markdownGreenfieldDocumentTextKey,
  type MarkdownGreenfieldDocument,
} from "./markdown-greenfield-document";

export const MARKDOWN_GREENFIELD_ASYNC_DOCUMENT_MIN_CHARS = 60_000;
export const MARKDOWN_GREENFIELD_DOCUMENT_WORKER_LOCAL_STORAGE_KEY =
  "retab:markdown-document-worker";
export const MARKDOWN_GREENFIELD_DOCUMENT_WORKER_SEARCH_PARAM =
  "markdownDocumentWorker";

const MARKDOWN_GREENFIELD_DOCUMENT_WORKER_READY_TIMEOUT_MS = 800;
const MARKDOWN_GREENFIELD_DOCUMENT_ENTRY_CACHE_LIMIT = 16;

type MarkdownIdleWindow = Window &
  typeof globalThis & {
    requestIdleCallback?: Window["requestIdleCallback"];
  };

type MarkdownDocumentState =
  | { status: "failed"; error: Error }
  | { status: "pending" }
  | { status: "ready"; document: MarkdownGreenfieldDocument };

type MarkdownDocumentEntry = {
  key: string;
  listeners: Set<() => void>;
  started: boolean;
  state: MarkdownDocumentState;
  text: string;
};

type MarkdownDocumentWorkerRequest = {
  id: number;
  text: string;
  type: "parse";
};

type MarkdownDocumentWorkerResponse =
  | {
      type: "ready";
    }
  | {
      document: MarkdownGreenfieldDocument;
      id: number;
      ok: true;
      type: "result";
    }
  | {
      failure: "clone_failed" | "parse_failed";
      id: number;
      message: string;
      ok: false;
      type: "result";
    };

const markdownDocumentEntries = new Map<string, MarkdownDocumentEntry>();
let nextMarkdownDocumentWorkerRequestId = 1;

export function useMarkdownGreenfieldDocument(text: string) {
  const shouldLoadAsync =
    text.length >= MARKDOWN_GREENFIELD_ASYNC_DOCUMENT_MIN_CHARS;
  const syncDocument = React.useMemo(
    () => (shouldLoadAsync ? null : createMarkdownGreenfieldDocument(text)),
    [shouldLoadAsync, text],
  );
  const entry = React.useMemo(
    () => (shouldLoadAsync ? getMarkdownDocumentEntry(text) : null),
    [shouldLoadAsync, text],
  );
  const asyncState = React.useSyncExternalStore(
    React.useCallback(
      (onStoreChange) => {
        if (!entry) return () => {};
        entry.listeners.add(onStoreChange);
        startMarkdownDocumentEntry(entry);
        return () => {
          entry.listeners.delete(onStoreChange);
        };
      },
      [entry],
    ),
    React.useCallback(() => entry?.state ?? null, [entry]),
    () => null,
  );

  if (syncDocument) return syncDocument;
  if (!asyncState || asyncState.status === "pending") return null;
  if (asyncState.status === "failed") throw asyncState.error;
  return asyncState.document;
}

function getMarkdownDocumentEntry(text: string) {
  const key = markdownGreenfieldDocumentTextKey(text);
  const existing = markdownDocumentEntries.get(key);
  if (existing?.text === text) return existing;

  const entry: MarkdownDocumentEntry = {
    key,
    listeners: new Set(),
    started: false,
    state: { status: "pending" },
    text,
  };
  markdownDocumentEntries.set(key, entry);
  evictMarkdownDocumentEntries(key);
  return entry;
}

function evictMarkdownDocumentEntries(currentKey: string) {
  for (const [key, entry] of markdownDocumentEntries) {
    if (
      markdownDocumentEntries.size <=
      MARKDOWN_GREENFIELD_DOCUMENT_ENTRY_CACHE_LIMIT
    ) {
      return;
    }
    if (key === currentKey || entry.listeners.size > 0) continue;
    markdownDocumentEntries.delete(key);
  }
}

function startMarkdownDocumentEntry(entry: MarkdownDocumentEntry) {
  if (entry.started || entry.state.status !== "pending") return;
  entry.started = true;

  if (typeof Worker !== "undefined" && isMarkdownDocumentWorkerEnabled()) {
    try {
      startMarkdownDocumentWorker(entry);
      return;
    } catch {
      startMarkdownDocumentFallback(entry);
      return;
    }
  }

  startMarkdownDocumentFallback(entry);
}

function startMarkdownDocumentWorker(entry: MarkdownDocumentEntry) {
  const worker = new Worker(
    new URL("./markdown-greenfield-document.worker.ts", import.meta.url),
    { type: "module" },
  );
  const id = nextMarkdownDocumentWorkerRequestId++;
  let isSettled = false;

  const fallBackToMainThread = () => {
    if (isSettled) return;
    isSettled = true;
    window.clearTimeout(readyTimeoutId);
    if (!isCurrentMarkdownDocumentEntry(entry)) {
      worker.terminate();
      return;
    }
    worker.terminate();
    startMarkdownDocumentFallback(entry);
  };
  const readyTimeoutId = window.setTimeout(() => {
    fallBackToMainThread();
  }, MARKDOWN_GREENFIELD_DOCUMENT_WORKER_READY_TIMEOUT_MS);

  worker.onmessage = (event: MessageEvent<unknown>) => {
    const message = markdownDocumentWorkerResponseFromValue(event.data);
    if (!message) {
      fallBackToMainThread();
      return;
    }

    if (message.type === "ready") {
      window.clearTimeout(readyTimeoutId);
      try {
        worker.postMessage({
          id,
          text: entry.text,
          type: "parse",
        } satisfies MarkdownDocumentWorkerRequest);
      } catch {
        fallBackToMainThread();
      }
      return;
    }
    if (message.id !== id || isSettled) {
      return;
    }
    isSettled = true;
    window.clearTimeout(readyTimeoutId);
    worker.terminate();
    if (!isCurrentMarkdownDocumentEntry(entry)) return;
    if (message.ok) {
      publishMarkdownDocumentState(entry, {
        document: freezeMarkdownGreenfieldDocument(message.document),
        status: "ready",
      });
      return;
    }
    if (message.failure === "clone_failed") {
      startMarkdownDocumentFallback(entry);
      return;
    }
    publishMarkdownDocumentState(entry, {
      error: new Error(message.message),
      status: "failed",
    });
  };
  worker.onerror = fallBackToMainThread;
  worker.onmessageerror = fallBackToMainThread;
}

function startMarkdownDocumentFallback(entry: MarkdownDocumentEntry) {
  scheduleMarkdownDocumentTask(() => {
    if (!isCurrentMarkdownDocumentEntry(entry)) return;
    try {
      publishMarkdownDocumentState(entry, {
        document: createMarkdownGreenfieldDocument(entry.text),
        status: "ready",
      });
    } catch (error) {
      publishMarkdownDocumentState(entry, {
        error:
          error instanceof Error
            ? error
            : new Error("Could not parse Markdown."),
        status: "failed",
      });
    }
  });
}

function scheduleMarkdownDocumentTask(callback: () => void) {
  if (typeof window === "undefined") return;
  const browserWindow = window as MarkdownIdleWindow;
  const runWhenIdle = () => {
    if (browserWindow.requestIdleCallback) {
      browserWindow.requestIdleCallback(callback, { timeout: 120 });
      return;
    }
    browserWindow.setTimeout(callback, 0);
  };

  if (browserWindow.requestAnimationFrame) {
    browserWindow.requestAnimationFrame(() => {
      browserWindow.setTimeout(runWhenIdle, 0);
    });
    return;
  }
  browserWindow.setTimeout(runWhenIdle, 0);
}

function publishMarkdownDocumentState(
  entry: MarkdownDocumentEntry,
  state: MarkdownDocumentState,
) {
  if (!isCurrentMarkdownDocumentEntry(entry)) return;
  entry.state = state;
  for (const listener of entry.listeners) listener();
}

function isCurrentMarkdownDocumentEntry(entry: MarkdownDocumentEntry) {
  const current = markdownDocumentEntries.get(entry.key);
  return current === entry && current.text === entry.text;
}

function isMarkdownDocumentWorkerEnabled() {
  if (typeof window === "undefined") return false;
  const urlFlag = readMarkdownDocumentWorkerSearchFlag(window.location.search);
  if (urlFlag != null) return urlFlag;
  return readMarkdownDocumentWorkerStorageFlag() ?? true;
}

function readMarkdownDocumentWorkerSearchFlag(search: string) {
  try {
    const value = new URLSearchParams(search).get(
      MARKDOWN_GREENFIELD_DOCUMENT_WORKER_SEARCH_PARAM,
    );
    return markdownDocumentWorkerFlagValue(value);
  } catch {
    return null;
  }
}

function readMarkdownDocumentWorkerStorageFlag() {
  try {
    return markdownDocumentWorkerFlagValue(
      window.localStorage.getItem(
        MARKDOWN_GREENFIELD_DOCUMENT_WORKER_LOCAL_STORAGE_KEY,
      ),
    );
  } catch {
    return null;
  }
}

function markdownDocumentWorkerFlagValue(value: string | null) {
  if (value == null) return null;
  switch (value.trim().toLowerCase()) {
    case "1":
    case "true":
    case "yes":
    case "on":
    case "worker":
      return true;
    case "0":
    case "false":
    case "no":
    case "off":
    case "main":
      return false;
    default:
      return null;
  }
}

function markdownDocumentWorkerResponseFromValue(
  value: unknown,
): MarkdownDocumentWorkerResponse | null {
  if (!value || typeof value !== "object") return null;
  const response = value as Partial<MarkdownDocumentWorkerResponse>;
  if (response.type === "ready") return { type: "ready" };
  if (response.type !== "result" || typeof response.id !== "number") {
    return null;
  }
  if (response.ok === true && response.document) {
    return response as MarkdownDocumentWorkerResponse;
  }
  if (
    response.ok === false &&
    (response.failure === "clone_failed" ||
      response.failure === "parse_failed") &&
    typeof response.message === "string"
  ) {
    return response as MarkdownDocumentWorkerResponse;
  }
  return null;
}

import { createMarkdownGreenfieldDocument } from "./markdown-greenfield-document";

type MarkdownDocumentWorkerRequest = {
  id: number;
  text: string;
  type: "parse";
};

type MarkdownDocumentWorkerResponse =
  | {
      type: "ready";
    }
  | {
      document: ReturnType<typeof createMarkdownGreenfieldDocument>;
      id: number;
      ok: true;
      type: "result";
    }
  | {
      failure: "clone_failed" | "parse_failed";
      id: number;
      message: string;
      ok: false;
      type: "result";
    };

self.postMessage({ type: "ready" } satisfies MarkdownDocumentWorkerResponse);

self.onmessage = (event: MessageEvent<MarkdownDocumentWorkerRequest>) => {
  const { id, text, type } = event.data;
  if (type !== "parse") {
    postMarkdownDocumentWorkerError({
      failure: "parse_failed",
      id,
      message: "Markdown document worker received an invalid request.",
    });
    return;
  }

  let document: ReturnType<typeof createMarkdownGreenfieldDocument>;
  try {
    document = createMarkdownGreenfieldDocument(text);
  } catch (error) {
    postMarkdownDocumentWorkerError({
      failure: "parse_failed",
      id,
      message:
        error instanceof Error ? error.message : "Could not parse Markdown.",
    });
    return;
  }

  try {
    assertStructuredCloneable(document);
    self.postMessage({
      document,
      id,
      ok: true,
      type: "result",
    } satisfies MarkdownDocumentWorkerResponse);
  } catch (error) {
    postMarkdownDocumentWorkerError({
      failure: "clone_failed",
      id,
      message:
        error instanceof Error
          ? error.message
          : "Markdown document worker payload is not structured-clone safe.",
    });
  }
};

function assertStructuredCloneable(value: unknown) {
  if (typeof structuredClone === "function") {
    structuredClone(value);
    return;
  }

  if (typeof MessageChannel === "function") {
    const channel = new MessageChannel();
    try {
      channel.port2.postMessage(value);
    } finally {
      channel.port1.close();
      channel.port2.close();
    }
    return;
  }

  throw new Error("Structured clone probe is unavailable.");
}

function postMarkdownDocumentWorkerError({
  failure,
  id,
  message,
}: {
  failure: "clone_failed" | "parse_failed";
  id: number;
  message: string;
}) {
  self.postMessage({
    failure,
    id,
    message,
    ok: false,
    type: "result",
  } satisfies MarkdownDocumentWorkerResponse);
}

"use client";

import type {
  MarkdownGreenfieldBlock,
  MarkdownGreenfieldChunk,
  MarkdownGreenfieldDocument,
} from "./markdown-greenfield-document";

// The chunk reading column's max inline size (the old max-w-4xl, 56rem at
// the 16px root). Shared with the surface motion resolver: the align
// translate that hides the close-leg recenter must agree with the markup
// about where the column's margin clamps.
export const MARKDOWN_GREENFIELD_CHUNK_MAX_INLINE_SIZE = 896;
const CHUNK_PADDING_X = 32;
const DOCUMENT_PADDING_TOP = CHUNK_PADDING_X;
const DOCUMENT_PADDING_BOTTOM = CHUNK_PADDING_X;
const MIN_CHUNK_HEIGHT = 64;
// Tuned to the rendered typography (15.5px body at leading-relaxed ≈ 25px,
// 14px mono code at leading-5 = 20px) so estimates track measured heights and
// scroll correction stays minimal.
const BODY_LINE_HEIGHT = 25;
const MONO_LINE_HEIGHT = 20;
const APPROX_BODY_CHAR_WIDTH = 7.9;
const APPROX_MONO_CHAR_WIDTH = 7.8;
export const MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION =
  "greenfield-layout-rich-blocks-v7";
const MARKDOWN_TABLE_VIRTUALIZATION_ROW_THRESHOLD = 80;
const MARKDOWN_TABLE_VIRTUALIZED_HEIGHT = 640;
const LAYOUT_CACHE_LIMIT = 64;
const ESTIMATED_HEIGHT_CACHE_LIMIT = 12;

const markdownGreenfieldLayoutDocumentIds = new WeakMap<
  MarkdownGreenfieldDocument,
  number
>();
const markdownGreenfieldLayoutCache = new Map<
  string,
  {
    document: MarkdownGreenfieldDocument;
    frame: MarkdownGreenfieldFrame;
  }
>();
const markdownGreenfieldEstimatedHeightCaches = new WeakMap<
  MarkdownGreenfieldDocument,
  Map<string, readonly number[]>
>();
let nextMarkdownGreenfieldLayoutDocumentId = 1;

export type MarkdownGreenfieldFrame = {
  chunks: MarkdownGreenfieldChunkFrame[];
  totalHeight: number;
  width: number;
};

export type MarkdownGreenfieldChunkFrame = {
  bottom: number;
  height: number;
  id: string;
  index: number;
  measuredHeight: number | null;
  sourceEndLine: number;
  sourceStartLine: number;
  top: number;
};

export type MarkdownGreenfieldMeasuredHeights = {
  /** Compact revision key for the current measured-height snapshot. */
  cacheKey?: string;
  get(
    chunk: MarkdownGreenfieldChunk,
    context: MarkdownGreenfieldMeasurementContext,
  ): number | undefined;
};

export type MarkdownGreenfieldMeasurementContext = {
  fontScale: number;
  policyVersion: string;
  width: number;
};

export function layoutMarkdownGreenfieldDocument({
  contentWidth,
  document,
  fontScale,
  measuredHeights,
}: {
  contentWidth: number;
  document: MarkdownGreenfieldDocument;
  fontScale: number;
  measuredHeights?: MarkdownGreenfieldMeasuredHeights;
}): MarkdownGreenfieldFrame {
  const width = Math.max(1, contentWidth);
  const context = {
    fontScale,
    policyVersion: MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION,
    width,
  };
  const measuredHeightsCacheKey = measuredHeights?.cacheKey ?? null;
  const shouldCacheFrame = !measuredHeights || measuredHeightsCacheKey != null;
  const cacheKey = markdownGreenfieldLayoutCacheKey({
    context,
    document,
    measuredHeightsCacheKey,
  });
  if (shouldCacheFrame) {
    const cached = markdownGreenfieldLayoutCache.get(cacheKey);
    if (cached?.document === document) {
      markdownGreenfieldLayoutCache.delete(cacheKey);
      markdownGreenfieldLayoutCache.set(cacheKey, cached);
      return cached.frame;
    }
  }

  const estimatedHeights = readMarkdownGreenfieldEstimatedHeights({
    context,
    document,
  });
  const chunks: MarkdownGreenfieldChunkFrame[] = [];
  let y = DOCUMENT_PADDING_TOP;

  for (const [chunkIndex, chunk] of document.chunks.entries()) {
    const estimatedHeight = estimatedHeights[chunkIndex] ?? MIN_CHUNK_HEIGHT;
    const measuredHeight = readMarkdownGreenfieldMeasuredHeight({
      chunk,
      context,
      measuredHeights,
    });
    const height = Math.max(
      MIN_CHUNK_HEIGHT,
      measuredHeight == null ? estimatedHeight : measuredHeight,
    );
    chunks.push({
      bottom: y + height,
      height,
      id: chunk.id,
      index: chunk.index,
      measuredHeight,
      sourceEndLine: chunk.sourceEndLine,
      sourceStartLine: chunk.sourceStartLine,
      top: y,
    });
    y += height;
  }

  const frame = freezeMarkdownGreenfieldFrame({
    chunks,
    totalHeight: chunks.length ? y + DOCUMENT_PADDING_BOTTOM : 0,
    width,
  });
  if (shouldCacheFrame) {
    markdownGreenfieldLayoutCache.set(cacheKey, { document, frame });
    while (markdownGreenfieldLayoutCache.size > LAYOUT_CACHE_LIMIT) {
      const oldestKey = markdownGreenfieldLayoutCache.keys().next().value;
      if (!oldestKey) break;
      markdownGreenfieldLayoutCache.delete(oldestKey);
    }
  }
  return frame;
}

function readMarkdownGreenfieldEstimatedHeights({
  context,
  document,
}: {
  context: MarkdownGreenfieldMeasurementContext;
  document: MarkdownGreenfieldDocument;
}) {
  const cacheKey = markdownGreenfieldEstimateCacheKey(context);
  const cache = markdownGreenfieldEstimateCacheForDocument(document);
  const cached = cache.get(cacheKey);
  if (cached) {
    cache.delete(cacheKey);
    cache.set(cacheKey, cached);
    return cached;
  }

  const blocksById = new Map(document.blocks.map((block) => [block.id, block]));
  const estimatedHeights = Object.freeze(
    document.chunks.map((chunk) =>
      estimateMarkdownGreenfieldChunkHeight({
        blocks: chunk.blockIds
          .map((blockId) => blocksById.get(blockId))
          .filter((block): block is MarkdownGreenfieldBlock => Boolean(block)),
        fontScale: context.fontScale,
        width: context.width,
      }),
    ),
  );
  cache.set(cacheKey, estimatedHeights);
  while (cache.size > ESTIMATED_HEIGHT_CACHE_LIMIT) {
    const oldestKey = cache.keys().next().value;
    if (!oldestKey) break;
    cache.delete(oldestKey);
  }
  return estimatedHeights;
}

function estimateMarkdownGreenfieldChunkHeight({
  blocks,
  fontScale,
  width,
}: {
  blocks: readonly MarkdownGreenfieldBlock[];
  fontScale: number;
  width: number;
}) {
  const textWidth = Math.max(1, width - CHUNK_PADDING_X * 2);
  const height = blocks.reduce(
    (sum, block) =>
      sum +
      estimateMarkdownGreenfieldBlockHeight({
        block,
        fontScale,
        textWidth,
      }),
    0,
  );
  return Math.max(MIN_CHUNK_HEIGHT, height);
}

function estimateMarkdownGreenfieldBlockHeight({
  block,
  fontScale,
  textWidth,
}: {
  block: MarkdownGreenfieldBlock;
  fontScale: number;
  textWidth: number;
}) {
  if (block.kind === "thematicBreak") return 36 * fontScale;
  if (block.kind === "frontmatter") {
    const lines = Math.max(1, block.sourceLineCount);
    return (72 + lines * MONO_LINE_HEIGHT) * fontScale;
  }
  if (block.kind === "footnotes")
    return estimateTextBlock(block, textWidth, fontScale, 0.9);
  if (block.kind === "heading") {
    return estimateTextBlock(block, textWidth, fontScale, 1.3) + 18 * fontScale;
  }
  if (block.kind === "diagram") return 360 * fontScale;
  if (block.kind === "math") return 120 * fontScale;
  if (block.kind === "component") return 160 * fontScale;
  if (block.kind === "code") {
    const lines = Math.max(1, block.sourceLineCount);
    return 48 * fontScale + lines * MONO_LINE_HEIGHT * fontScale;
  }
  if (block.kind === "table") {
    const rows = Math.max(2, block.sourceLineCount);
    if (rows >= MARKDOWN_TABLE_VIRTUALIZATION_ROW_THRESHOLD) {
      return MARKDOWN_TABLE_VIRTUALIZED_HEIGHT * fontScale;
    }
    return (48 + rows * 36) * fontScale;
  }
  if (block.kind === "image") return 280 * fontScale;
  if (block.isHostile) return 420 * fontScale;
  return estimateTextBlock(block, textWidth, fontScale, 1);
}

function estimateTextBlock(
  block: MarkdownGreenfieldBlock,
  textWidth: number,
  fontScale: number,
  multiplier: number,
) {
  const charWidth =
    block.kind === "code" ? APPROX_MONO_CHAR_WIDTH : APPROX_BODY_CHAR_WIDTH;
  const columns = Math.max(12, Math.floor(textWidth / (charWidth * fontScale)));
  const visualLines = block.sourceLineLengths.reduce(
    (sum, lineLength) => sum + Math.max(1, Math.ceil(lineLength / columns)),
    0,
  );
  return (
    16 * fontScale + visualLines * BODY_LINE_HEIGHT * fontScale * multiplier
  );
}

function readMarkdownGreenfieldMeasuredHeight({
  chunk,
  context,
  measuredHeights,
}: {
  chunk: MarkdownGreenfieldChunk;
  context: MarkdownGreenfieldMeasurementContext;
  measuredHeights?: MarkdownGreenfieldMeasuredHeights;
}) {
  if (!measuredHeights) return null;
  const measuredHeight = measuredHeights.get(chunk, context);
  if (
    typeof measuredHeight === "number" &&
    Number.isFinite(measuredHeight) &&
    measuredHeight > 0
  ) {
    return measuredHeight;
  }
  return null;
}

function markdownGreenfieldLayoutCacheKey({
  context,
  document,
  measuredHeightsCacheKey,
}: {
  context: MarkdownGreenfieldMeasurementContext;
  document: MarkdownGreenfieldDocument;
  measuredHeightsCacheKey: string | null;
}) {
  return [
    markdownGreenfieldLayoutDocumentId(document),
    Math.round(context.width * 100) / 100,
    context.fontScale.toFixed(4),
    context.policyVersion,
    measuredHeightsCacheKey ?? "unmeasured",
  ].join(":");
}

function markdownGreenfieldEstimateCacheKey(
  context: MarkdownGreenfieldMeasurementContext,
) {
  return [
    Math.round(context.width * 100) / 100,
    context.fontScale.toFixed(4),
    context.policyVersion,
  ].join(":");
}

function markdownGreenfieldEstimateCacheForDocument(
  document: MarkdownGreenfieldDocument,
) {
  let cache = markdownGreenfieldEstimatedHeightCaches.get(document);
  if (cache) return cache;
  cache = new Map();
  markdownGreenfieldEstimatedHeightCaches.set(document, cache);
  return cache;
}

function markdownGreenfieldLayoutDocumentId(
  document: MarkdownGreenfieldDocument,
) {
  const existing = markdownGreenfieldLayoutDocumentIds.get(document);
  if (existing) return existing;
  const next = nextMarkdownGreenfieldLayoutDocumentId++;
  markdownGreenfieldLayoutDocumentIds.set(document, next);
  return next;
}

function freezeMarkdownGreenfieldFrame(frame: MarkdownGreenfieldFrame) {
  for (const chunk of frame.chunks) Object.freeze(chunk);
  Object.freeze(frame.chunks);
  return Object.freeze(frame);
}

