export type ViewerFormat =
  | "pdf"
  | "image"
  | "text"
  | "csv"
  | "docx"
  | "xlsx"
  | "pptx"
  | "file";

export type ViewerErrorDomain =
  | "resource"
  | "format"
  | "state"
  | "unsupported"
  | "unknown";

export type ResourceErrorKind =
  | "fetch_failed"
  | "http_error"
  | "aborted"
  | "invalid_range"
  | "partial_content"
  | "too_large"
  | "unsupported_capability"
  | "unknown";

export type ResourceTooLargeReason = "bytes" | "lines";

export class ResourceError extends Error {
  readonly domain = "resource";
  readonly kind: ResourceErrorKind;
  readonly status?: number;
  readonly tooLargeReason?: ResourceTooLargeReason;
  override readonly cause?: unknown;

  constructor({
    kind,
    message,
    status,
    tooLargeReason,
    cause,
  }: {
    kind: ResourceErrorKind;
    message: string;
    status?: number;
    tooLargeReason?: ResourceTooLargeReason;
    cause?: unknown;
  }) {
    super(message);
    this.name = "ResourceError";
    this.kind = kind;
    this.status = status;
    this.tooLargeReason = tooLargeReason;
    this.cause = cause;
  }
}

export type ViewerFormatErrorKind =
  | "bounds"
  | "decode_failed"
  | "disposed"
  | "index_out_of_range"
  | "load_failed"
  | "parse_failed"
  | "render_failed"
  | "worker_failed"
  | "unknown";

export interface ViewerFormatErrorMapperOptions {
  kind: ViewerFormatErrorKind;
  message: string;
}

export class ViewerFormatError extends Error {
  readonly domain = "format";
  readonly format: ViewerFormat;
  readonly kind: ViewerFormatErrorKind;
  override readonly cause?: unknown;

  constructor({
    format,
    kind,
    message,
    cause,
  }: {
    format: ViewerFormat;
    kind: ViewerFormatErrorKind;
    message: string;
    cause?: unknown;
  }) {
    super(message);
    this.name = "ViewerFormatError";
    this.format = format;
    this.kind = kind;
    this.cause = cause;
  }
}

export type ViewerStateErrorKind =
  | "invalid_bounds"
  | "invalid_target"
  | "out_of_range"
  | "stale_resource"
  | "unknown";

export class ViewerStateError extends Error {
  readonly domain = "state";
  readonly format?: ViewerFormat;
  readonly kind: ViewerStateErrorKind;
  override readonly cause?: unknown;

  constructor({
    format,
    kind,
    message,
    cause,
  }: {
    format?: ViewerFormat;
    kind: ViewerStateErrorKind;
    message: string;
    cause?: unknown;
  }) {
    super(message);
    this.name = "ViewerStateError";
    this.format = format;
    this.kind = kind;
    this.cause = cause;
  }
}

export class ViewerUnsupportedError extends Error {
  readonly domain = "unsupported";
  readonly format?: ViewerFormat;
  readonly sourceKind?: string;
  override readonly cause?: unknown;

  constructor({
    format,
    sourceKind,
    message,
    cause,
  }: {
    format?: ViewerFormat;
    sourceKind?: string;
    message: string;
    cause?: unknown;
  }) {
    super(message);
    this.name = "ViewerUnsupportedError";
    this.format = format;
    this.sourceKind = sourceKind;
    this.cause = cause;
  }
}

export interface ViewerErrorInfo {
  domain: ViewerErrorDomain;
  format?: ViewerFormat;
  kind: string;
  message: string;
  status?: number;
  isRetryable: boolean;
  isDownloadUseful: boolean;
  userMessage: string;
  cause?: unknown;
}

export interface ViewerErrorContext {
  format?: ViewerFormat;
  sourceKind?: "url" | "blob" | "text";
  canDownload?: boolean;
  retry?: "auto" | "always" | "never";
}

export function isAbortError(error: unknown): boolean {
  return (
    (error instanceof DOMException && error.name === "AbortError") ||
    (error instanceof Error && error.name === "AbortError")
  );
}

export function isResourceError(error: unknown): error is ResourceError {
  return (
    error instanceof ResourceError ||
    isErrorLike(error, "ResourceError", "resource")
  );
}

export function isViewerFormatError(
  error: unknown,
): error is ViewerFormatError {
  return (
    error instanceof ViewerFormatError ||
    isErrorLike(error, "ViewerFormatError", "format")
  );
}

export function isViewerStateError(error: unknown): error is ViewerStateError {
  return (
    error instanceof ViewerStateError ||
    isErrorLike(error, "ViewerStateError", "state")
  );
}

export function isViewerUnsupportedError(
  error: unknown,
): error is ViewerUnsupportedError {
  return (
    error instanceof ViewerUnsupportedError ||
    isErrorLike(error, "ViewerUnsupportedError", "unsupported")
  );
}

export function toViewerErrorInfo(
  error: unknown,
  context: ViewerErrorContext = {},
): ViewerErrorInfo {
  const canDownload = context.canDownload ?? true;

  if (isResourceError(error)) {
    return {
      domain: "resource",
      format: context.format,
      kind: error.kind,
      message: error.message,
      status: error.status,
      isRetryable: retryable(
        context,
        resourceErrorDefaultRetry(error, context),
      ),
      isDownloadUseful: canDownload && error.kind !== "aborted",
      userMessage: resourceErrorUserMessage(error),
      cause: error.cause,
    };
  }

  if (isViewerFormatError(error)) {
    const format = error.format ?? context.format;
    return {
      domain: "format",
      format,
      kind: error.kind,
      message: error.message,
      isRetryable: retryable(
        context,
        formatErrorDefaultRetry(error, context, format),
      ),
      isDownloadUseful: canDownload,
      userMessage: formatErrorUserMessage(format, error.kind, error),
      cause: error.cause,
    };
  }

  if (isViewerStateError(error)) {
    return {
      domain: "state",
      format: error.format ?? context.format,
      kind: error.kind,
      message: error.message,
      isRetryable: retryable(context, false),
      isDownloadUseful: canDownload,
      userMessage: stateErrorUserMessage(error.kind),
      cause: error.cause,
    };
  }

  if (isViewerUnsupportedError(error)) {
    return {
      domain: "unsupported",
      format: error.format ?? context.format,
      kind: "unsupported",
      message: error.message,
      isRetryable: retryable(context, false),
      isDownloadUseful: canDownload,
      userMessage: "This file cannot be previewed here.",
      cause: error.cause,
    };
  }

  if (isAbortError(error)) {
    return {
      domain: "resource",
      format: context.format,
      kind: "aborted",
      message: "Loading was cancelled.",
      isRetryable: retryable(context, false),
      isDownloadUseful: false,
      userMessage: "Loading was cancelled.",
      cause: error,
    };
  }

  const message = error instanceof Error ? error.message : String(error);
  return {
    domain: "unknown",
    format: context.format,
    kind: "unknown",
    message,
    isRetryable: retryable(context, unknownErrorDefaultRetry(context)),
    isDownloadUseful: canDownload,
    userMessage: fallbackUserMessage(context.format),
    cause: error,
  };
}

function isErrorLike(error: unknown, name: string, domain: ViewerErrorDomain) {
  if (!error || typeof error !== "object") return false;
  const candidate = error as {
    name?: unknown;
    domain?: unknown;
    kind?: unknown;
  };
  return (
    (candidate.name === name || candidate.domain === domain) &&
    typeof candidate.kind === "string"
  );
}

function retryable(context: ViewerErrorContext, fallback: boolean) {
  if (context.retry === "always") return true;
  if (context.retry === "never") return false;
  return fallback;
}

function resourceErrorDefaultRetry(
  error: ResourceError,
  context: ViewerErrorContext,
) {
  if (error.kind === "aborted") return false;
  if (error.kind === "invalid_range") return false;
  if (error.kind === "too_large") return false;
  if (error.kind === "unsupported_capability") return false;
  return context.sourceKind === "url";
}

function formatErrorDefaultRetry(
  error: ViewerFormatError,
  context: ViewerErrorContext,
  format: ViewerFormat | undefined,
) {
  if (format === "text" && error.kind === "bounds") return false;
  if (error.kind === "disposed") return false;
  if (error.kind === "index_out_of_range") return false;
  if (format === "docx") return true;
  return context.sourceKind === "url";
}

function unknownErrorDefaultRetry(context: ViewerErrorContext) {
  if (context.format === "docx") return true;
  return context.sourceKind === "url";
}

function resourceErrorUserMessage(error: ResourceError) {
  if (error.kind === "http_error") {
    return error.status
      ? `Failed to load file: ${error.status}.`
      : "Couldn't load this file.";
  }
  if (error.kind === "fetch_failed") return "Couldn't load this file.";
  if (error.kind === "aborted") return "Loading was cancelled.";
  if (error.kind === "invalid_range") return "This source range is invalid.";
  if (error.kind === "too_large") {
    return error.tooLargeReason === "lines"
      ? "This file has too many lines to preview."
      : "This file is too large to preview.";
  }
  if (error.kind === "partial_content") {
    return "This source returned partial content and cannot be previewed here.";
  }
  if (error.kind === "unsupported_capability") {
    return "This source cannot be previewed here.";
  }
  return "Couldn't load this file.";
}

function formatErrorUserMessage(
  format: ViewerFormat | undefined,
  kind: string,
  error?: unknown,
) {
  if (format === "pdf") return "Couldn't load this PDF.";
  if (format === "image") {
    if (kind === "index_out_of_range")
      return "This image page is out of range.";
    if (kind === "decode_failed") return "Couldn't decode this image.";
    return "Couldn't load this image.";
  }
  if (format === "text") {
    if (kind === "render_failed") return "Couldn't render this text file.";
    if (kind === "bounds") {
      const boundsError = error as {
        reason?: unknown;
        boundName?: unknown;
      };
      if (boundsError.reason === "lines") {
        return "This text file has too many lines to preview.";
      }
      if (boundsError.reason === "bytes") {
        return "This text file is too large to preview.";
      }
      if (typeof boundsError.boundName === "string") {
        return "Text viewer bounds are invalid.";
      }
    }
    return "Couldn't load this text file.";
  }
  if (format === "csv") return "Couldn't parse this table.";
  if (format === "docx") return "Couldn't render this document.";
  if (format === "xlsx") return "Couldn't parse this spreadsheet.";
  if (format === "pptx") {
    if (kind === "render_failed") return "Couldn't render this slide.";
    return "Couldn't load this presentation.";
  }
  return "Couldn't load this file.";
}

function stateErrorUserMessage(kind: ViewerStateErrorKind) {
  if (kind === "invalid_bounds") return "Viewer bounds are invalid.";
  if (kind === "invalid_target") return "The requested target is invalid.";
  if (kind === "out_of_range") return "The requested item is out of range.";
  if (kind === "stale_resource") return "This viewer state is no longer valid.";
  return "Couldn't load this file.";
}

function fallbackUserMessage(format: ViewerFormat | undefined) {
  if (format === "pdf") return "Couldn't load this PDF.";
  if (format === "image") return "Couldn't load this image.";
  if (format === "text") return "Couldn't load this text file.";
  if (format === "csv") return "Couldn't parse this table.";
  if (format === "docx") return "Couldn't load this document.";
  if (format === "xlsx") return "Couldn't load this spreadsheet.";
  if (format === "pptx") return "Couldn't load this presentation.";
  return "Couldn't load this file.";
}

"use client";

import * as React from "react";

const emptySubscribe = () => () => {};
const getClientSnapshot = () => true;
const getServerSnapshot = () => false;

/**
 * SSR gate: `false` on the server (and during hydration's first pass),
 * `true` on the client.
 *
 * This must stay a synchronous external-store read, NOT the
 * `useState(false)` + mount-effect flip. The flip pattern makes every
 * viewer mount its Suspense boundary in a later update; when two such
 * boundaries suspend on pending resources in the same flush as other
 * commit-phase updates (viewer sidebar/geometry registration), React 19's
 * retry lanes desynchronize and re-attempt each other's boundary on every
 * commit — an unbounded synchronous suspend/retry loop that starves the
 * event loop (jsdom tests OOM; browsers busy-spin until the resource
 * resolves). With the store read, client renders suspend on mount, which
 * never enters that loop. Regression-guarded in
 * tests/pdf-viewer-thumbnails.test.tsx ("shares one document resource…").
 */
export function useIsClient(): boolean {
  return React.useSyncExternalStore(
    emptySubscribe,
    getClientSnapshot,
    getServerSnapshot,
  );
}

"use client";

export function patchKeyedDomChildren<Item, Element extends HTMLElement>({
  createElement,
  getKey,
  items,
  parent,
  updateElement,
}: {
  createElement: (item: Item) => Element;
  getKey: (item: Item) => string;
  items: readonly Item[];
  parent: HTMLElement;
  updateElement: (element: Element, item: Item) => void;
}) {
  const existing = new Map<string, Element>();
  for (const child of Array.from(parent.children)) {
    if (!(child instanceof HTMLElement)) {
      child.remove();
      continue;
    }

    const key = child.dataset.projectionKey;
    if (!key || existing.has(key)) {
      child.remove();
      continue;
    }
    existing.set(key, child as Element);
  }

  let cursor: ChildNode | null = parent.firstChild;
  const usedKeys = new Set<string>();

  for (const item of items) {
    const key = getKey(item);
    let element = existing.get(key);
    if (!element || usedKeys.has(key)) {
      element = createElement(item);
      element.dataset.projectionKey = key;
    }
    usedKeys.add(key);
    updateElement(element, item);

    if (element.parentNode !== parent || element !== cursor) {
      parent.insertBefore(element, cursor);
      continue;
    }
    cursor = cursor.nextSibling;
  }

  while (cursor) {
    const next = cursor.nextSibling;
    cursor.remove();
    cursor = next;
  }
}

"use client";

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export const TEXT_SCROLL_INTERACTION_RESTORE_DELAY_MS = 120;

export type ScrollInteractionSnapshot = {
  overflowTarget: HTMLElement | null;
  overflowX: InlineStyleSnapshot | null;
  pointerEvents: InlineStyleSnapshot;
  target: HTMLElement;
};

type InlineStyleSnapshot = {
  priority: string;
  value: string;
};

export function useTextViewerScrollInteractions<Viewport extends HTMLElement>({
  getInteractionTarget,
  getOverflowTarget,
  onScroll,
  viewportRef,
}: {
  getInteractionTarget: () => HTMLElement | null | undefined;
  getOverflowTarget?: () => HTMLElement | null | undefined;
  onScroll: (viewport: Viewport) => void;
  viewportRef: React.RefObject<Viewport | null>;
}) {
  const restoreTimerRef = React.useRef(0);
  const snapshotRef = React.useRef<ScrollInteractionSnapshot | null>(null);

  useKeyedMountEffect(
    joinEffectKey([
      getInteractionTarget,
      getOverflowTarget,
      onScroll,
      viewportRef,
    ]),
    () => {
      const viewport = viewportRef.current;
      if (!viewport) return;

      const handleScroll = () => {
        suspendTextViewerScrollInteractions({
          getInteractionTarget,
          getOverflowTarget,
          snapshotRef,
        });
        if (restoreTimerRef.current) {
          window.clearTimeout(restoreTimerRef.current);
        }
        restoreTimerRef.current = window.setTimeout(() => {
          restoreTimerRef.current = 0;
          restoreTextViewerScrollInteractions(snapshotRef);
        }, TEXT_SCROLL_INTERACTION_RESTORE_DELAY_MS);
        onScroll(viewport);
      };

      viewport.addEventListener("scroll", handleScroll, { passive: true });
      return () => {
        viewport.removeEventListener("scroll", handleScroll);
        if (restoreTimerRef.current) {
          window.clearTimeout(restoreTimerRef.current);
          restoreTimerRef.current = 0;
        }
        restoreTextViewerScrollInteractions(snapshotRef);
      };
    },
  );
}

export function suspendTextViewerScrollInteractions({
  getInteractionTarget,
  getOverflowTarget,
  snapshotRef,
}: {
  getInteractionTarget: () => HTMLElement | null | undefined;
  getOverflowTarget?: () => HTMLElement | null | undefined;
  snapshotRef: React.MutableRefObject<ScrollInteractionSnapshot | null>;
}) {
  const target = getInteractionTarget();
  if (!target) {
    restoreTextViewerScrollInteractions(snapshotRef);
    return;
  }

  const overflowTarget = isMobileSafari()
    ? (getOverflowTarget?.() ?? target.parentElement ?? target)
    : null;
  const current = snapshotRef.current;
  if (
    current &&
    current.target === target &&
    current.overflowTarget === overflowTarget
  ) {
    target.style.pointerEvents = "none";
    overflowTarget?.style.setProperty("overflow-x", "hidden");
    return;
  }

  restoreTextViewerScrollInteractions(snapshotRef);
  snapshotRef.current = {
    overflowTarget,
    overflowX: overflowTarget
      ? readInlineStyle(overflowTarget, "overflow-x")
      : null,
    pointerEvents: readInlineStyle(target, "pointer-events"),
    target,
  };
  target.style.pointerEvents = "none";
  overflowTarget?.style.setProperty("overflow-x", "hidden");
}

export function restoreTextViewerScrollInteractions(
  snapshotRef: React.MutableRefObject<ScrollInteractionSnapshot | null>,
) {
  const snapshot = snapshotRef.current;
  if (!snapshot) return;

  restoreInlineStyle(snapshot.target, "pointer-events", snapshot.pointerEvents);
  if (snapshot.overflowTarget && snapshot.overflowX) {
    restoreInlineStyle(
      snapshot.overflowTarget,
      "overflow-x",
      snapshot.overflowX,
    );
  }
  snapshotRef.current = null;
}

function isMobileSafari() {
  if (typeof navigator === "undefined") return false;
  const userAgent = navigator.userAgent;
  return (
    /Safari/i.test(userAgent) &&
    /Mobile/i.test(userAgent) &&
    !/CriOS|FxiOS|EdgiOS/i.test(userAgent)
  );
}

function readInlineStyle(
  element: HTMLElement,
  propertyName: string,
): InlineStyleSnapshot {
  return {
    priority: element.style.getPropertyPriority(propertyName),
    value: element.style.getPropertyValue(propertyName),
  };
}

function restoreInlineStyle(
  element: HTMLElement,
  propertyName: string,
  snapshot: InlineStyleSnapshot,
) {
  if (!snapshot.value) {
    element.style.removeProperty(propertyName);
    return;
  }
  element.style.setProperty(propertyName, snapshot.value, snapshot.priority);
}

import Prism from "prismjs";

import type { CodeTokenLeaf } from "./code-viewer-syntax-protocol";

Prism.manual = true;

const coreLanguages = new Set(["css", "javascript", "markup"]);
const languageLoaders: Record<string, () => Promise<unknown>> = {
  bash: () => import("prismjs/components/prism-bash"),
  diff: () => import("prismjs/components/prism-diff"),
  dockerfile: () => import("prismjs/components/prism-docker"),
  go: () => import("prismjs/components/prism-go"),
  java: () => import("prismjs/components/prism-java"),
  json: () => import("prismjs/components/prism-json"),
  jsx: () => import("prismjs/components/prism-jsx"),
  markdown: () => import("prismjs/components/prism-markdown"),
  python: () => import("prismjs/components/prism-python"),
  rust: () => import("prismjs/components/prism-rust"),
  ruby: () => import("prismjs/components/prism-ruby"),
  sql: () => import("prismjs/components/prism-sql"),
  tsx: async () => {
    await Promise.all([
      import("prismjs/components/prism-typescript"),
      import("prismjs/components/prism-jsx"),
    ]);
    return import("prismjs/components/prism-tsx");
  },
  typescript: () => import("prismjs/components/prism-typescript"),
  yaml: () => import("prismjs/components/prism-yaml"),
};

const loadingLanguages = new Map<string, Promise<void>>();

export function isCodePrismLanguageLoaded(languageId: string) {
  return Boolean(Prism.languages[languageId]);
}

export function isCodePrismLanguageSupported(languageId: string) {
  return coreLanguages.has(languageId) || languageId in languageLoaders;
}

export async function ensureCodePrismLanguage(languageId: string) {
  if (isCodePrismLanguageLoaded(languageId)) return;
  if (coreLanguages.has(languageId)) return;

  let loading = loadingLanguages.get(languageId);
  if (!loading) {
    const loadLanguage = languageLoaders[languageId];
    if (!loadLanguage) {
      loading = Promise.reject(
        new Error(`Unsupported code syntax language: ${languageId}`),
      );
    } else {
      loading = loadLanguage().then(() => undefined);
    }
    loadingLanguages.set(languageId, loading);
  }

  await loading;
}

export function tokenizeCodeLine(languageId: string, line: string) {
  const grammar = Prism.languages[languageId] ?? null;
  if (!grammar) return null;
  return flattenCodeTokens(Prism.tokenize(line, grammar));
}

function flattenCodeTokens(
  tokens: Array<string | Prism.Token>,
  parentKind = "",
  leaves: CodeTokenLeaf[] = [],
): CodeTokenLeaf[] {
  for (const token of tokens) {
    if (typeof token === "string") {
      leaves.push({ kind: parentKind, text: token });
    } else if (Array.isArray(token.content)) {
      flattenCodeTokens(
        token.content as Array<string | Prism.Token>,
        token.type,
        leaves,
      );
    } else if (typeof token.content === "string") {
      leaves.push({ kind: token.type, text: token.content });
    } else {
      flattenCodeTokens([token.content as Prism.Token], token.type, leaves);
    }
  }
  return leaves;
}

export const CODE_LINE_TOKENIZE_MAX = 2000;

export type CodeTokenLeaf = {
  kind: string;
  text: string;
};

export type CodeSyntaxWorkerRequest = {
  type: "tokenize";
  requestId: number;
  generation: number;
  languageId: string;
  lines: string[];
};

export type CodeSyntaxWorkerResponse =
  | {
      type: "tokens";
      requestId: number;
      generation: number;
      languageId: string;
      results: CodeSyntaxWorkerTokenResult[];
    }
  | {
      type: "error";
      requestId: number;
      generation: number;
      languageId: string;
      message: string;
    };

export type CodeSyntaxWorkerTokenResult = {
  line: string;
  tokens: CodeTokenLeaf[] | null;
};

export function shouldTokenizeCodeLine(line: string) {
  return line.length > 0 && line.length <= CODE_LINE_TOKENIZE_MAX;
}

import type { CodeTokenLeaf } from "./code-viewer-syntax-protocol";

export function markdownCodeTokensToHtml({
  highlightPattern,
  line,
  tokens,
}: {
  highlightPattern: string;
  line: string;
  tokens: readonly CodeTokenLeaf[] | null;
}) {
  if (!tokens) return null;
  if (!tokens.length) return " ";
  const highlightStart = highlightPattern ? line.indexOf(highlightPattern) : -1;
  const highlightEnd =
    highlightStart >= 0 ? highlightStart + highlightPattern.length : -1;
  let cursor = 0;
  let html = "";

  for (const token of tokens) {
    const tokenStart = cursor;
    const tokenEnd = cursor + token.text.length;
    cursor = tokenEnd;
    html += tokenToHtml({
      highlightEnd,
      highlightStart,
      token,
      tokenEnd,
      tokenStart,
    });
  }

  return html || " ";
}

function tokenToHtml({
  highlightEnd,
  highlightStart,
  token,
  tokenEnd,
  tokenStart,
}: {
  highlightEnd: number;
  highlightStart: number;
  token: CodeTokenLeaf;
  tokenEnd: number;
  tokenStart: number;
}) {
  const inner = tokenTextToHtml({
    highlightEnd,
    highlightStart,
    text: token.text,
    textEnd: tokenEnd,
    textStart: tokenStart,
  });
  if (!token.kind || !/^[a-z-]+$/.test(token.kind)) return inner;
  return `<span class="cv-token-${token.kind}" data-pretext-code-token="${token.kind}">${inner}</span>`;
}

function tokenTextToHtml({
  highlightEnd,
  highlightStart,
  text,
  textEnd,
  textStart,
}: {
  highlightEnd: number;
  highlightStart: number;
  text: string;
  textEnd: number;
  textStart: number;
}) {
  if (
    highlightStart < 0 ||
    textEnd <= highlightStart ||
    textStart >= highlightEnd
  ) {
    return escapeHtml(text);
  }

  const before = text.slice(0, Math.max(0, highlightStart - textStart));
  const highlighted = text.slice(
    Math.max(0, highlightStart - textStart),
    Math.min(text.length, highlightEnd - textStart),
  );
  const after = text.slice(Math.min(text.length, highlightEnd - textStart));
  return [
    escapeHtml(before),
    highlighted
      ? `<span data-highlighted-chars="">${escapeHtml(highlighted)}</span>`
      : "",
    escapeHtml(after),
  ].join("");
}

function escapeHtml(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

export const MARKDOWN_CODE_HIGHLIGHT_BATCH_SIZE = 64;
export const MARKDOWN_CODE_HIGHLIGHT_CACHE_LIMIT = 4096;
export const MARKDOWN_CODE_HIGHLIGHT_RENDERER_VERSION = 1;

export type MarkdownCodeHighlightLineRequest = {
  index: number;
  line: string;
};

export type MarkdownCodeHighlightLineResult = {
  html: string | null;
  index: number;
};

export type MarkdownCodeHighlightWorkerRequest = {
  generation: number;
  highlightPattern: string;
  languageId: string;
  lines: MarkdownCodeHighlightLineRequest[];
  requestId: number;
  type: "highlight";
};

export type MarkdownCodeHighlightWorkerResponse =
  | {
      generation: number;
      languageId: string;
      requestId: number;
      results: MarkdownCodeHighlightLineResult[];
      type: "highlighted";
    }
  | {
      generation: number;
      languageId: string;
      message: string;
      requestId: number;
      type: "error";
    };

import { shouldTokenizeCodeLine } from "./code-viewer-syntax-protocol";
import {
  ensureCodePrismLanguage,
  tokenizeCodeLine,
} from "./code-viewer-syntax-prism";
import { markdownCodeTokensToHtml } from "./markdown-greenfield-code-highlight-html";
import type {
  MarkdownCodeHighlightWorkerRequest,
  MarkdownCodeHighlightWorkerResponse,
} from "./markdown-greenfield-code-highlight-protocol";

const workerSelf = self as unknown as {
  onmessage:
    | ((event: MessageEvent<MarkdownCodeHighlightWorkerRequest>) => void)
    | null;
  postMessage(message: MarkdownCodeHighlightWorkerResponse): void;
};

function post(message: MarkdownCodeHighlightWorkerResponse) {
  workerSelf.postMessage(message);
}

async function highlightInWorker(request: MarkdownCodeHighlightWorkerRequest) {
  await ensureCodePrismLanguage(request.languageId);
  post({
    generation: request.generation,
    languageId: request.languageId,
    requestId: request.requestId,
    results: request.lines.map(({ index, line }) => ({
      html: shouldTokenizeCodeLine(line)
        ? markdownCodeTokensToHtml({
            highlightPattern: request.highlightPattern,
            line,
            tokens: tokenizeCodeLine(request.languageId, line),
          })
        : null,
      index,
    })),
    type: "highlighted",
  });
}

workerSelf.onmessage = (
  event: MessageEvent<MarkdownCodeHighlightWorkerRequest>,
) => {
  const request = event.data;
  if (request.type !== "highlight") return;

  void highlightInWorker(request).catch((error) => {
    post({
      generation: request.generation,
      languageId: request.languageId,
      message: error instanceof Error ? error.message : String(error),
      requestId: request.requestId,
      type: "error",
    });
  });
};

